import type { MeaningPack } from '../../types';

export const taSundaraVerses3: MeaningPack = {
  lang: 'ta',
  texts: {
    'sundarakanda-27': {
      verses: {
        '0.0': 'சீதை இவ்வாறு கடுமையாகப் பேசவே, சினத்தால் தன்னிலை இழந்த அரக்கியருள் சிலர் தீயவனான ராவணனிடம் அதைச் சொல்லச் சென்றனர்.',
        '0.1': 'பின்னர் அச்சம் தரும் தோற்றமுடைய அரக்கியர் சீதையை அணுகி, அவளுக்குக் கேடு விளைவிக்கும் ஒரே நோக்குடைய கடுஞ்சொற்களை மீண்டும் கூறினர்.',
        '0.2': '“தீய முடிவுடைய இழிந்தவளே சீதை! இன்றே, இப்போதே அரக்கியர் உன் இந்த ஊனை விரும்பியபடி தின்றுவிடுவர்.”',
        '0.3': 'அந்த இழிந்த பெண்கள் சீதையை இவ்வாறு மிரட்டுவதைக் கண்டு, அப்போதுதான் விழித்தெழுந்த முதிய அரக்கி திரிஜடை பேசினாள்.',
        '0.4': '“இழிந்தவர்களே, உங்களையே நீங்கள் தின்னுங்கள்; ஜனகனின் அன்பு மகளும் தசரதனின் மருமகளுமான சீதையை நீங்கள் தின்னமாட்டீர்கள்.”',
        '0.5': '“இன்று நான் மயிர்க்கூச்செறியும் கொடிய கனவொன்றைக் கண்டேன்; அது அரக்கர்களின் அழிவையும் இவள் கணவனின் வெற்றியையும் குறிக்கிறது.”',
        '0.6': 'திரிஜடை இவ்வாறு கூறவே, சினத்தால் கொதித்த அரக்கியர் அனைவரும் அஞ்சி திரிஜடையிடம் இவ்வாறு சொன்னார்கள்:',
        '0.7': '“இரவில் நீ கண்ட இக்கனவு எத்தகையது, சொல்.” அரக்கியரின் வாயிலிருந்து வந்த அச்சொல்லைக் கேட்டு,',
        '0.8': 'திரிஜடை அப்போது கனவின் செய்தியைக் கூறினாள்: “வானில் செல்லும் தந்தத்தாலான தெய்வீகப் பல்லக்கில்,',
        '0.9': 'ஆயிரம் குதிரைகள் பூட்டிய அதில், வெண்மாலையும் வெண்ணாடையும் அணிந்த ராகவன் லக்ஷ்மணனுடன் தானே ஏறி வந்தான்.',
        '0.10': '“இன்று கனவில் வெண்ணாடை உடுத்த சீதை கடல் சூழ்ந்த வெண்மலை மீது அமர்ந்திருப்பதைக் கண்டேன்;',
        '0.11': '“கதிரவனுடன் ஒளி போல அவள் ராமனுடன் இணைந்திருந்தாள். மீண்டும் ராகவன் நான்கு தந்தங்களுடைய பெரிய யானையின் மீது ஏறியிருப்பதைக் கண்டேன்;',
        '0.12': '“மலை போன்ற அந்த யானையின் மேல் அவன் லக்ஷ்மணனுடன் விளங்கினான். பின்பு கதிரவர்களைப் போலத் தம் ஒளியால் ஒளிர்ந்த அவ்விருவரும்,',
        '0.13': '“வெண்மாலையும் ஆடையும் அணிந்து ஜானகியிடம் வந்தனர். அப்போது அம்மலையின் உச்சியில் வானில் நின்ற அந்த யானையின்,',
        '0.14': '“கணவன் பற்றிக்கொண்ட ஜானகி அதன் தோளின் மேல் ஏறினாள்; பின் அந்தத் தாமரைக் கண்ணாள் கணவனின் மடியிலிருந்து எழும்பி,',
        '0.15': '“கைகளால் சந்திரனையும் சூரியனையும் தடவுவதைக் கண்டேன். பின்னர் அவ்விரு இளவரசர்களையும் அகன்ற கண்ணுடைய சீதையையும் தாங்கிய அச்சிறந்த யானை இலங்கையின் மேல் நின்றது.',
        '0.16': '“எட்டு வெள்ளை எருதுகள் பூட்டிய தேரில் காகுத்ஸ்தன் தன் மனைவி சீதையுடன் தானே இங்கு வந்தான்;',
        '0.17': '“வெண்மாலையும் ஆடையும் அணிந்து லக்ஷ்மணனுடன் வந்தான். பின்பு வேறோரிடத்தில் உண்மையான வீரமுடைய ராமனைக் கண்டேன்;',
        '0.18': '“அவ்வீரன் தம்பி லக்ஷ்மணனுடனும் சீதையுடனும் கதிரவன் போல் ஒளிரும் தெய்வீகப் புஷ்பக விமானத்தில் ஏறி,',
        '0.19': '“அந்தப் புருஷோத்தமன் வடதிசை நோக்கிப் புறப்பட்டான். இவ்வாறு கனவில் விஷ்ணுவின் வீரமுடைய ராமனைக் கண்டேன்,',
        '0.20': '“தம்பி லக்ஷ்மணனுடனும் மனைவி சீதையுடனும். மிகுந்த ஒளியுடைய ராமனைத் தேவர்களும் அசுரர்களும் வெல்ல இயலாது;',
        '0.21': '“பாவிகளுக்கு விண்ணுலகம் கிட்டாதது போல அரக்கர்களோ பிறரோ அவனை வெல்ல முடியாது. மொட்டையடித்து எண்ணெய் பூசிய ராவணனையும் கண்டேன்;',
        '0.22': '“சிவப்பு ஆடை அணிந்து, குடித்து மயங்கி, அலரிப் பூமாலை சூடியிருந்தான்; இன்று ராவணன் புஷ்பக விமானத்திலிருந்து தரையில் விழுந்தான்.',
        '0.23': '“மொட்டைத் தலையுடன், கருப்பு ஆடையுடன் அவனை ஒரு பெண் இழுத்துச் செல்வதை மீண்டும் கண்டேன்; சிவந்த மாலையும் பூச்சும் அணிந்து கழுதைகள் பூட்டிய தேரில்,',
        '0.24': '“எண்ணெய் குடித்துக்கொண்டு, சிரித்து ஆடிக்கொண்டு, மனம் குழம்பிப் புலன்கள் கலங்கி, கழுதையின் மேல் விரைவாகத் தென்திசை நோக்கிச் சென்றான்.',
        '0.25': '“மீண்டும் அரக்கர் தலைவனான ராவணன் அச்சத்தால் மயங்கிக் கழுதையிலிருந்து தலைகீழாகத் தரையில் விழுந்ததைக் கண்டேன்.',
        '0.26': '“திடீரென எழுந்து, பதறி, அச்சத்தால் வருந்தி, மயக்கத்தால் தள்ளாடி, பித்தன் போல ஆடையின்றி, பல இழிசொற்களைப் பிதற்றினான்.',
        '0.27': '“நரகம் போன்ற, துர்நாற்றமுடைய, தாங்கவியலாத, கொடிய, இருண்ட அழுக்குச் சேற்றில் விரைந்து புகுந்து ராவணன் அங்கே மூழ்கினான்.',
        '0.28': '“தெற்கு நோக்கிச் சென்று சேறில்லாத ஒரு மடுவில் புகுந்தான்; சிவப்பு ஆடை அணிந்த ஒரு பெண் தசக்ரீவனின் கழுத்தில் கயிறு கட்டி,',
        '0.29': '“உடலெல்லாம் சேறு பூசிய கரிய பெண் அவனை யமனின் திசைக்கு இழுத்துச் சென்றாள். அவ்வாறே அங்கே பெருவலிமையுடைய கும்பகர்ணனையும் கண்டேன்;',
        '0.30': '“ராவணனின் மைந்தர்கள் அனைவரும் மொட்டையடித்து எண்ணெய் பூசியிருந்தனர். தசக்ரீவன் பன்றியின் மேலும், இந்திரஜித் கடல்பன்றியின் (சிம்சுமாரம்) மேலும்,',
        '0.31': '“கும்பகர்ணன் ஒட்டகத்தின் மேலும் தென்திசை நோக்கிப் புறப்பட்டனர். அங்கே வெண்குடையுடன் விபீஷணன் ஒருவனை மட்டும் கண்டேன்;',
        '0.32': '“அவன் வெண்மாலையும் ஆடையும் அணிந்து, வெண்சந்தனம் பூசி, சங்கு துந்துபி முழக்கங்களாலும் ஆடல் பாடல்களாலும் சிறப்பிக்கப்பட்டிருந்தான்.',
        '0.33': '“மலை போன்ற, இடிமுழக்கம் போல் பிளிறும், நான்கு தந்தங்களுடைய தெய்வீக யானையின் மீது ஏறி விபீஷணன் அங்கே இருந்தான்;',
        '0.34': '“தன் நான்கு அமைச்சர்களுடன் வானில் நின்றிருந்தான்.',
        '0.35': '“சிவப்பு மாலையும் சிவப்பு ஆடையும் அணிந்து குடிக்கும் அரக்கர்களின் பெரும் கூட்டம் பாடல் இசை முழக்கத்துடன் நடந்தது.',
        '0.36': '“குதிரைகள், தேர்கள், யானைகளுடன் இந்த அழகிய இலங்கை நகரம் கோபுரங்களும் தோரணங்களும் உடைந்து கடலில் விழுந்திருப்பதாகத் தோன்றியது.',
        '0.37': '“ராவணனால் காக்கப்படும் இலங்கையை ராமனின் தூதனான வேகமுடைய ஒரு வானரன் எரித்ததைக் கனவில் கண்டேன்.',
        '0.38': '“சாம்பலால் பொலிவிழந்த இலங்கையில் அரக்கப் பெண்கள் அனைவரும் எண்ணெய் குடித்து வெறிகொண்டு உரத்த குரலில் சிரித்தனர்.',
        '0.39': '“கும்பகர்ணன் முதலான இந்த அரக்கர் தலைவர்கள் அனைவரும் சிவப்பு ஆடை அணிந்து சாணக் குழியில் புகுந்தனர்.',
        '0.40': '“விலகிச் செல்லுங்கள், பாருங்கள்: ராகவன் சீதையை அடைவான். பெருஞ்சினம் கொண்ட அவன் அரக்கர்களுடன் உங்களையும் கொல்வான்.',
        '0.41': '“வனவாசத்தில் தன்னைப் பின்தொடர்ந்த அன்புக்குரிய, பெருமதிப்புக்குரிய மனைவியை ஏசுவதையோ மிரட்டுவதையோ ராகவன் பொறுக்க மாட்டான்.',
        '0.42': '“ஆகவே கொடுஞ்சொற்கள் போதும்; இனிய சொற்களையே பேசுங்கள். வைதேகியிடம் வேண்டிக்கொள்வோம்; இதுவே எனக்குச் சரியெனப்படுகிறது.',
        '0.43': '“துயருற்ற எந்தப் பெண்ணைக் குறித்து இத்தகைய கனவு காணப்படுகிறதோ அவள் பல துயரங்களிலிருந்து விடுபட்டு மேலான இன்பத்தை அடைவாள்.',
        '0.44': '“அரக்கியரே, அவளை ஏசியிருந்தாலும் இப்போது வேண்டிக்கொள்ளுங்கள்; வாதம் எதற்கு? ராகவனால் அரக்கர்களுக்குக் கொடிய அச்சம் நெருங்கியுள்ளது.',
        '0.45': '“ஜனகனின் மகளான மைதிலி வணக்கத்தாலேயே மனம் இரங்குவாள்; அரக்கியரே, பெரும் அச்சத்திலிருந்து உங்களைக் காக்க இவளே வல்லவள்.',
        '0.46': '“மேலும், அகன்ற கண்ணுடைய இவளின் உறுப்புகளில் சிறிதளவு தீய அடையாளமும் எனக்குத் தென்படவில்லை.',
        '0.47': '“அவளது ஒளி மங்கியிருப்பதால் மட்டுமே துயர் வந்துள்ளது என ஐயுறுகிறேன்; துயருக்குத் தகாத இத்தேவியை வானில் நிற்பதாகக் கண்டேன்.',
        '0.48': '“வைதேகியின் நோக்கம் நிறைவேறுவது நெருங்கியுள்ளதைக் காண்கிறேன்: அரக்கர் வேந்தனின் அழிவும் ராகவனின் வெற்றியும்.',
        '0.49': '“அவள் பெரும் இனிய செய்தியைக் கேட்கப் போவதற்கு இது நிமித்தம்: தாமரை இதழ் போல் நீண்ட அவள் கண் துடிப்பது காணப்படுகிறது.',
        '0.50': '“வைதேகியின் ஒரு கை — வலது அல்ல, இடது — திடீரென்று சிலிர்த்துச் சற்று நடுங்குகிறது.',
        '0.51': '“யானையின் துதிக்கை போன்ற அவளது ஒப்பற்ற இடது தொடையும் நடுங்கி, ராகவன் எதிரே நிற்கிறான் என்று சொல்வது போல் உள்ளது.',
        '0.52': '“கிளையிலுள்ள தன் கூட்டில் புகுந்த ஒரு பறவை மீண்டும் மீண்டும் இனிய வரவேற்பு ஒலி எழுப்பி மகிழ்ந்து அவளைத் தூண்டுவது போல் உள்ளது.”',
        '0.53': 'அப்போது நாணமுடைய இளம் சீதை கணவனின் வெற்றியை எண்ணி மகிழ்ந்து, “அது உண்மையானால் நான் நிச்சயம் உங்களுக்கு அடைக்கலமாவேன்” என்றாள்.',
        '0.54': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் இருபத்தேழாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-28': {
      verses: {
        '0.0': 'அரக்கர் வேந்தன் ராவணனின் அந்த இனிமையற்ற சொற்களைக் கேட்டு வருந்திய சீதை, காட்டின் விளிம்பில் சிங்கத்திடம் சிக்கிய இளம் பெண்யானை போல நடுங்கினாள்.',
        '0.1': 'அரக்கியர் நடுவில் அகப்பட்டு ராவணனின் சொற்களால் கடுமையாக மிரட்டப்பட்ட அஞ்சும் சீதை, ஆளில்லாக் காட்டில் கைவிடப்பட்ட சிறுமி போலப் புலம்பினாள்.',
        '0.2': '“ஐயோ, காலம் வருமுன் மரணம் இல்லை என்று உலகில் சான்றோர் சொல்வது உண்மைதான்; இப்படி மிரட்டப்பட்டும் புண்ணியமற்ற நான் கணப்பொழுதும் உயிருடன் இருக்கிறேனே.',
        '0.3': '“இன்பமிழந்து பல துயரங்களால் நிறைந்த என் இதயம் உறுதியானதுதான்; இடி தாக்கிய மலைமுகடு போல இன்று அது ஆயிரம் துண்டுகளாகப் பிளக்கவில்லையே.',
        '0.4': '“இதில் என் குற்றம் ஏதுமில்லை; காணச் சகிக்காத இவனால் நான் கொல்லப்பட வேண்டியவள். இருபிறப்பாளன் இருபிறப்பாளன் அல்லாதவனுக்கு மந்திரம் கொடுக்க இயலாதது போல நான் இவனுக்கு என் உள்ளத்தைக் கொடுக்க இயலேன்.',
        '0.5': '“அந்த உலகநாதன் வராவிட்டால், கருவிலுள்ள சிசுவை அறுவை மருத்துவன் அறுப்பது போல அந்த இழிந்த அரக்கர் வேந்தன் விரைவில் கூரிய ஆயுதங்களால் என் உறுப்புகளை வெட்டுவான்.',
        '0.6': '“ஐயோ, துயருற்ற எனக்கு இது மேலும் துயர்: அரசனின் ஆணையால் மரணதண்டனை பெற்றுக் கட்டுண்ட திருடனுக்கு இரவு கழிவது போல இவ்விரண்டு மாதங்களும் விரைவில் கழிந்துவிடும்.',
        '0.7': '“ஹா ராமா! ஹா லக்ஷ்மணா! ஹா சுமித்திரையே! ஹா ராமனின் அன்னையே, என் அன்னையரே! புயலில் சிக்கிய பெருங்கடல் படகு போல அதிருஷ்டமற்ற நான் இங்கே அழிகிறேன்.',
        '0.8': '“மான் உருவம் தாங்கிய அந்த உயிரால் என் பொருட்டு அவ்விரு வலிய இளவரசர்களும் மின்னல் தாக்கிய இரு சிறந்த சிங்கங்கள் போலக் கொல்லப்பட்டிருக்க வேண்டும்.',
        '0.9': '“அப்போது மான் உருவம் தாங்கிய காலனே அதிருஷ்டமற்ற என்னை மயக்கினான்; அதனால்தான் அறிவிழந்த நான் உத்தமர்களான ராம லக்ஷ்மணர் இருவரையும் அனுப்பிவிட்டேன்.',
        '0.10': '“ஹா சத்திய விரதனே, நீண்ட கைகளுடைய ராமா! ஹா முழுமதி போன்ற முகமுடையவனே! ஹா உயிருலகின் நலனும் அன்பும் உரியவனே! அரக்கர்களால் நான் கொல்லப்படப் போவதை நீ அறியாய்.',
        '0.11': '“வேறு தெய்வத்தை வணங்காமை, இந்தப் பொறுமை, தரையில் படுத்தல், அறத்தில் நியமம், என் கற்பு — இவையெல்லாம் நன்றி கெட்டவர்களுக்குச் செய்த உதவி போலப் பயனற்றுப் போயின.',
        '0.12': '“நான் கடைப்பிடித்த அறம் வீண், இந்த ஒருவனையே கணவனாகக் கொண்ட நோன்பும் பொருளற்றது; ஏனெனில் உன்னைக் காணவில்லை; இளைத்து, நிறம் கெட்டு, உன்னைப் பிரிந்து, மீண்டும் சேர்வதில் நம்பிக்கை இழந்தேன்.',
        '0.13': '“தந்தையின் ஆணையை முறையாக நிறைவேற்றி, நோன்பை முடித்துக் காட்டிலிருந்து திரும்பிய நீ அச்சமின்றி, நோக்கம் நிறைவேறியவனாய் அகன்ற கண்ணுடைய பெண்களுடன் மகிழ்வாய் என்று எண்ணுகிறேன்.',
        '0.14': '“ஆனால் ராமா, உன்னையே விரும்பி, என் அழிவுக்கே நெடுங்காலம் உன்னிடம் உள்ளம் பிணைத்த நான், தவத்தையும் நோன்பையும் வீணாக நோற்று இவ்வுயிரைத் துறப்பேன். அதிருஷ்டமற்ற எனக்கு ஐயோ!',
        '0.15': '“நஞ்சாலோ கூரிய ஆயுதத்தாலோ விரைவில் உயிர் துறப்பேன்; ஆனால் அரக்கனின் இல்லத்தில் எனக்கு நஞ்சோ ஆயுதமோ தருபவர் எவருமில்லை.”',
        '0.16': 'துயரால் வெந்து பலவாறு எண்ணிய சீதை தன் சடையைப் பற்றி, “இச்சடையால் தூக்கிட்டு விரைவில் யமனிடம் செல்வேன்” என்று எண்ணினாள்.',
        '0.17': 'மென்மையான உடலுடைய அவள் அம்மரத்தின் கிளையைப் பற்றி நின்றாள்; அழகிய அவள் ராமனையும் ராமனின் தம்பியையும் தன் குலத்தையும் நினைக்கையில்,',
        '0.18': 'அப்போது அவளுக்குத் துயர் நீக்கும், துணிவு தரும், உலகில் சிறந்த, முன்பும் பலித்த பல நல்ல நிமித்தங்கள் தோன்றின.',
        '0.19': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் இருபத்தெட்டாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-29': {
      verses: {
        '0.0': 'அவ்வாறு வருந்தி, மகிழ்ச்சி இழந்து, மனம் மிகவும் தளர்ந்திருந்த அந்தக் குற்றமற்ற நங்கையை, செல்வம் பெற்றவனைப் பணியாளர் அடைவது போல நல்ல நிமித்தங்கள் அடைந்தன.',
        '0.1': 'அழகிய கூந்தலுடைய அவளது வளைந்த இமைமயிர்களால் சூழப்பட்ட, கருவிழியும் அகன்ற வெண்மையும் கொண்ட அழகிய இடக்கண், மீன் மோதிய செந்தாமரை போலத் துடித்தது.',
        '0.2': 'அழகிய, உருண்டு திரண்ட, விலையுயர்ந்த அகில் சந்தனங்களுக்குத் தகுந்த, ஒப்பற்ற காதலன் நெடுங்காலம் தலையணையாகக் கொண்ட அவளது இடக்கை விரைவாக நடுங்கியது.',
        '0.3': 'ஒன்றோடொன்று நெருங்கிய அவ்விரண்டில் ஒன்றான, யானை அரசனின் துதிக்கை போலத் திரண்ட அவள் தொடை துடித்து, ராமன் எதிரே நிற்கிறான் என்று அறிவித்தது.',
        '0.4': 'அங்கே நின்ற ஒப்பற்ற கண்களும் கூர்மையான பற்களும் உடைய அழகியின் சற்றுப் புழுதி படிந்த பொன்னிற அழகிய ஆடை சிறிது நழுவியது.',
        '0.5': 'முன்பும் நன்கு பலித்த இந்நிமித்தங்களாலும் பிறவற்றாலும் தூண்டப்பட்ட அழகிய புருவமுடையவள், காற்றும் வெயிலும் வாட்டி அழிந்த விதை மழையால் துளிர்ப்பது போல மகிழ்ந்தாள்.',
        '0.6': 'கோவைப்பழம் போன்ற இதழ்கள், அழகிய கண்கள், புருவங்கள், கூந்தல், வளைந்த இமைமயிர்கள், வெண்மையாய் ஒளிரும் பற்கள் கொண்ட அவள் முகம் ராகுவின் வாயிலிருந்து விடுபட்ட சந்திரன் போல மீண்டும் ஒளிர்ந்தது.',
        '0.7': 'துயர் நீங்கி, சோர்வு அகன்று, வெம்மை தணிந்து, மகிழ்ச்சியால் உள்ளம் விழித்த அந்த உத்தமி, குளிர்மதி உதித்த வளர்பிறை இரவு போலத் தன் முகத்தால் விளங்கினாள்.',
        '0.8': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் இருபத்தொன்பதாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-30': {
      verses: {
        '0.0': 'வீரனான ஹனுமானும் சீதையின் சொற்களையும் திரிஜடையின் சொற்களையும் அரக்கியரின் மிரட்டல்களையும் அனைத்தையும் உள்ளபடியே கேட்டான்.',
        '0.1': 'நந்தனவனத்துத் தெய்வம் போன்ற அத்தேவியைப் பார்த்துக்கொண்டே அவ்வானரன் பலவாறு சிந்திக்கலானான்.',
        '0.2': '“ஆயிரக்கணக்கான, பல்லாயிரக்கணக்கான வானரர்கள் எல்லாத் திசைகளிலும் தேடும் அவளை நான் கண்டடைந்தேன்.',
        '0.3': '“பகைவனின் வலிமையைக் கவனிக்கும் திறமையான ஒற்றன் போல மறைவாகத் திரிந்து இதுவரை இவற்றையெல்லாம் பார்த்துவிட்டேன்:',
        '0.4': '“அரக்கர்களின் தனித்தன்மைகள், இந்நகரம், அரக்கர் தலைவன் ராவணனின் வல்லமை — அனைத்தும் கவனிக்கப்பட்டன.',
        '0.5': '“எல்லா உயிர்களிடமும் இரக்கமுடைய அந்த அளவிலாதவனின் மனைவி கணவனைக் காண ஏங்கும்போது அவளைத் தேற்றுவது முறை.',
        '0.6': '“முன்பு துயர் அறியாத, இப்போது துயரத்திற்கு முடிவு காணாத முழுமதி முகத்தாளை நான் தேற்றுவேன்.',
        '0.7': '“துயரால் மனம் நொந்த இக்கற்புடையாளைத் தேற்றாமல் நான் சென்றால் என் பயணம் குற்றமுடையதாகும்.',
        '0.8': '“நான் சென்றுவிட்டால், புகழுடைய இவ்விளவரசி ஜானகி காப்பு எதுவும் காணாமல் உயிரை விட்டுவிடக்கூடும்.',
        '0.9': '“அவ்வாறே சீதையைக் காண ஏங்கும் முழுமதி முகமுடைய அந்த நீண்ட கையனையும் தேற்றுவது முறை.',
        '0.10': '“ஆனால் இரவில் திரியும் அரக்கியர் முன்னிலையில் அவளுடன் பேசுவது தகாது. அப்படியானால் இதை எவ்வாறு செய்வது? நான் உண்மையில் இக்கட்டில் இருக்கிறேன்.',
        '0.11': '“எஞ்சிய இவ்விரவில் நான் அவளைத் தேற்றாவிட்டால் அவள் உயிர் துறப்பாள் என்பதில் சிறிதும் ஐயமில்லை.',
        '0.12': '“‘சீதை எனக்கு என்ன செய்தி சொன்னாள்?’ என்று ராமன் கேட்டால், அந்த மெல்லிடையாளுடன் பேசாமல் நான் அவனுக்கு என்ன பதில் சொல்வேன்?',
        '0.13': '“சீதையின் செய்தியின்றி நான் இங்கிருந்து விரைந்து சென்றால், காகுத்ஸ்தன் சினத்தால் கடுமையான கண்களால் என்னை எரித்தும் விடலாம்.',
        '0.14': '“ராமனுக்காக என் தலைவன் சுக்ரீவனைப் போருக்குத் தூண்டினாலும், படையுடன் அவன் வருவது வீணாகும்.',
        '0.15': '“ஆகவே அரக்கியரிடையே தக்க சமயம் பார்த்திருந்து, பெருந்துயரில் உள்ள இவளை இன்று மெல்லத் தேற்றுவேன்.',
        '0.16': '“நான் மிகச் சிறியவன், அதிலும் வானரன்; இருப்பினும் இங்கே திருத்தமான மனிதமொழியில் பேசுவேன்.',
        '0.17': '“ஆனால் அந்தணன் போலச் செம்மொழியில் பேசினால், சீதை என்னை ராவணன் என்று எண்ணி அஞ்சுவாள்.',
        '0.18': '“பொருளுள்ள பொதுவான மனிதமொழியிலேயே நான் நிச்சயமாகப் பேச வேண்டும்; அப்போதுதான் இக்குற்றமற்றவளைத் தேற்ற முடியும், வேறு வழியில் அல்ல.',
        '0.19': '“ஏற்கெனவே அரக்கர்களால் அச்சுறுத்தப்பட்ட ஜானகி என் உருவையும் பேச்சையும் கண்டு மீண்டும் அஞ்சுவாள்.',
        '0.20': '“அப்போது அச்சமுற்ற அந்த உறுதியுள்ள அகன்ற கண்ணாள், என்னை விரும்பிய உருவெடுக்கும் ராவணன் என்று எண்ணிக் கூச்சலிடக்கூடும்.',
        '0.21': '“சீதை கூச்சலிட்டால், பலவகை ஆயுதங்களுடன் கொடிய அரக்கியர் கூட்டம் யமனைப் போலத் திடீரென்று திரண்டுவிடும்.',
        '0.22': '“அப்போது விகாரமான முகங்களுடைய அவ்வலியவர்கள் என்னை எல்லாப் பக்கங்களிலும் சூழ்ந்து கொல்லவோ பிடிக்கவோ முயல்வர்.',
        '0.23': '“சிறந்த மரங்களின் கிளைகள், சிறுகிளைகள், அடிமரங்கள் மீது ஓடித் திரியும் என்னைக் கண்டு அவர்கள் ஐயமுறுவர்.',
        '0.24': '“வனத்தில் திரியும் என் பெரிய உருவைக் கண்டு அரக்கியர் அச்சத்தால் நடுங்கி விகாரமான குரலில் கத்துவர்.',
        '0.25': '“அப்போது அரக்கியர், அரக்கர் வேந்தனின் மாளிகையில் அவனால் நியமிக்கப்பட்ட அரக்கர்களையும் அழைப்பர்.',
        '0.26': '“சூலம், அம்பு, வாள் முதலான பல ஆயுதங்களைக் கையில் ஏந்திய அவர்கள் பதற்றத்தால் இம்மோதலுக்கு வேகமாகப் பாய்ந்து வருவர்.',
        '0.27': '“அவர்களால் சுற்றிலும் வளைக்கப்பட்டு நான் அரக்கர் படையை அழிப்பேன்; ஆனால் பெருங்கடலின் மறுகரையை அடைய இயலாமல் போகலாம்.',
        '0.28': '“அல்லது விரைந்து செயல்படும் பலர் சூழ்ந்து என்னைப் பிடிக்கக்கூடும்; அப்போது இவளது நோக்கமும் நிறைவேறாது, நானும் சிறைப்படுவேன்.',
        '0.29': '“அல்லது கொடுமையில் விருப்பமுள்ளவர்கள் இந்த ஜனகன் மகளையே கொல்லக்கூடும்; அப்போது ராம சுக்ரீவர்களின் இச்செயல் முழுதும் கெட்டுவிடும்.',
        '0.30': '“வழிகளே அறியப்படாத, அரக்கர்கள் சூழ்ந்த, கடலால் வளைக்கப்பட்ட இம்மறைவான இடத்தில் ஜானகி வசிக்கிறாள்.',
        '0.31': '“போரில் அரக்கர்களால் நான் கொல்லப்பட்டாலோ பிடிக்கப்பட்டாலோ, ராமனின் செயலை நிறைவேற்ற வேறு துணைவனை நான் காணவில்லை.',
        '0.32': '“எண்ணிப் பார்த்தாலும், நான் கொல்லப்பட்டால் நூறு யோஜனை அகலமுள்ள பெருங்கடலைத் தாண்டக்கூடிய வானரன் எவனும் தென்படவில்லை.',
        '0.33': '“ஆயிரக்கணக்கான அரக்கர்களைக் கொல்ல நான் நிச்சயம் வல்லவன்; ஆனால் பெருங்கடலின் மறுகரையை அடைய முடியாமல் போகலாம்.',
        '0.34': '“போர்கள் உறுதியற்றவை; ஐயத்துக்குரிய வழி எனக்கு உகந்ததல்ல. உறுதியான செயலை எந்த அறிவாளி ஐயத்துக்குரியதாக்குவான்?',
        '0.35': '“சீதையுடன் பேசுவதில் இப்பெரும் ஆபத்து உள்ளது; பேசாவிட்டால் வைதேகி உயிர் துறப்பாள்.',
        '0.36': '“இடம், காலம் இவற்றுக்கு மாறாக, தடுமாறும் தூதனிடம் சிக்கும்போது, நிறைவேறிய காரியங்களும் கதிரவன் உதயத்தில் இருள் போல அழிகின்றன.',
        '0.37': '“செய்யத் தக்கது, தகாதது பற்றிய உறுதியான அறிவும் பயன் தருவதில்லை; தம்மை அறிஞர் என்று எண்ணும் தூதர்கள் காரியங்களைக் கெடுக்கின்றனர்.',
        '0.38': '“காரியம் கெடாமல் இருப்பது எப்படி? நான் தடுமாறாமல் இருப்பது எப்படி? நான் கடலைத் தாண்டியது வீணாகாமல் இருப்பது எப்படி?',
        '0.39': '“அவள் என் சொற்களைக் கேட்டு அஞ்சாமல் இருப்பது எப்படி?” என்று சிந்தித்து அறிவுடைய ஹனுமான் ஒரு முடிவுக்கு வந்தான்.',
        '0.40': '“சலிப்பின்றிச் செயல்புரியும், அவளுக்கு உண்மையான உறவான ராமனைப் புகழ்ந்துரைத்து, அவனிடமே மனம் வைத்த இவளை அச்சுறுத்தாமல் இருப்பேன்.',
        '0.41': '“இக்ஷ்வாகுக்களில் சிறந்தவனும் தன்னை அறிந்தவனுமான ராமனைப் பற்றிய மங்கலமான, அறம் சார்ந்த சொற்களை முன்வைத்து,',
        '0.42': '“இனிய குரலில் பேசி அனைத்தையும் அவளுக்குக் கேட்கச் செய்வேன்; சீதை நம்பும்படி எல்லாவற்றையும் அமைப்பேன்.”',
        '0.43': 'இவ்வாறு பெரும் வல்லமையுடைய ஹனுமான் உலகநாதனின் அன்புக்குரியவளைப் பலவாறு நோக்கி, மரக்கிளைகளின் இடையே அமர்ந்து இனிமையும் உண்மையும் கொண்ட சொற்களைப் பேசினான்.',
        '0.44': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் முப்பதாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-31': {
      verses: {
        '0.0': 'இவ்வாறு பலவாறு சிந்தித்த அந்தப் பேரறிவாளன் வைதேகிக்குக் கேட்கும்படி இனிய சொற்களைக் கூறினான்.',
        '0.1': '“தேர்கள், யானைகள், குதிரைகள் நிறைந்த, புண்ணிய நடத்தையுடைய, பெரும்புகழ் பெற்ற, இக்ஷ்வாகுக்களில் சிறந்த புகழுடைய தசரதன் என்னும் அரசன் இருந்தான்.',
        '0.2': '“அவன் அரசமுனிவர்களில் குணத்தால் சிறந்தவன், தவத்தில் முனிவர்களுக்கு நிகரானவன், சக்கரவர்த்திகளின் குலத்தில் பிறந்தவன், வலிமையில் இந்திரனுக்கு இணையானவன்,',
        '0.3': '“அகிம்சையில் விருப்பமுள்ளவன், இழிவற்றவன், இரக்கமுள்ளவன், உண்மையான வீரமுடையவன், சிறந்த இக்ஷ்வாகு குலத்தின் செல்வன், செல்வத்தைப் பெருக்குபவன்,',
        '0.4': '“அரச இலக்கணங்கள் உடையவன், பெரும் சீருடையவன், அரசர்களில் காளை போன்றவன், நான்கு எல்லையுடைய பூமியில் புகழ்பெற்றவன், இன்பம் அளிப்பவன், தானும் இன்புற்றவன்.',
        '0.5': '“அவனுடைய அன்பு மூத்த மகன் சந்திரன் போன்ற முகமுடைய ராமன்; நுண்ணறிவுடையவன், வில்லாளிகள் அனைவரிலும் சிறந்தவன்,',
        '0.6': '“தன் ஒழுக்கத்தையும் தன்னவர்களையும் காப்பவன், உயிருலகையும் அறத்தையும் காப்பவன், பகைவரை வாட்டுபவன்.',
        '0.7': '“சத்தியம் தவறாத முதிய தந்தையின் சொல்லின்படி அவ்வீரன் மனைவியுடனும் தம்பியுடனும் காட்டுக்குச் சென்றான்.',
        '0.8': '“அப்பெருங்காட்டில் வேட்டையாடித் திரிந்த அவன், விரும்பிய உருவெடுக்கும் பல வீர அரக்கர்களைக் கொன்றான்.',
        '0.9': '“ஜனஸ்தானத்தின் அழிவையும் கரன் தூஷணன் கொல்லப்பட்டதையும் கேட்டு, சினத்தால் ராவணன் ஜானகியைக் கவர்ந்தான்,',
        '0.10': '“மான் உருவிலான மாயையால் காட்டில் ராமனை ஏமாற்றி. குற்றமற்ற தேவி சீதையைத் தேடிக்கொண்டு ராமன்',
        '0.11': '“காட்டில் சுக்ரீவன் என்னும் வானர நண்பனைப் பெற்றான். பின்னர் பகைவர் நகரங்களை வெல்லும் ராமன் வாலியைக் கொன்று',
        '0.12': '“மகாத்மாவான சுக்ரீவனுக்கு வானர அரசைக் கொடுத்தான். சுக்ரீவனால் ஏவப்பட்ட, விரும்பிய உருவெடுக்கும் வானரர்கள்',
        '0.13': '“ஆயிரக்கணக்கில் எல்லாத் திசைகளிலும் அத்தேவியைத் தேடுகின்றனர். நான் சம்பாதியின் சொல்லின்படி நூறு யோஜனை அகலமுள்ள',
        '0.14': '“கடலை அந்த அகன்ற கண்ணாளுக்காக வேகமாகத் தாண்டினேன். உருவம், நிறம், அடையாளங்கள் எவ்வாறு என்று',
        '0.15': '“ராகவனிடமிருந்து கேட்டேனோ அவ்வாறே இவள் — இவளை நான் கண்டடைந்தேன்.” இவ்வாறு கூறி அவ்வானரச் சிறந்தோன் அமைதியானான்.',
        '0.16': 'இதைக் கேட்ட ஜானகியும் பெருவியப்படைந்தாள். பின்னர் சுருண்ட குழலும் அழகிய கூந்தலும் உடைய அந்த அஞ்சும் நங்கை, கூந்தலால் மூடிய முகத்தை உயர்த்திச் சிம்சுபா மரத்தை நோக்கினாள்.',
        '0.17': 'குரங்கின் சொற்களைக் கேட்டு எல்லாத் திசைகளையும் இடைத்திசைகளையும் நோக்கிய சீதை, முழு மனதுடன் ராமனை நினைத்துப் பேரானந்தம் அடைந்தாள்.',
        '0.18': 'பக்கவாட்டிலும் மேலும் கீழும் நோக்கிய அவள், சிந்தைக்கெட்டாத அறிவுடைய, வானர அரசனின் அமைச்சனான, உதயமலையில் கதிரவன் போன்ற வாயுமைந்தனைக் கண்டாள்.',
        '0.19': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் முப்பத்தொன்றாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-32': {
      verses: {
        '0.0': 'அப்போது கிளைகளிடையே மறைந்திருந்த, வெண்ணாடை சுற்றிய, மின்னல் திரள் போலப் பொன்னிறமான அவனைக் கண்டு மனம் கலங்கிய அவள்,',
        '0.1': 'அங்கே பணிவுடையவனும் இனிமையாகப் பேசுபவனும், மலர்ந்த அசோகப் பூங்கொத்துப் போல ஒளிர்பவனும், உருக்கிய பொன் போன்ற கண்களுடையவனுமான குரங்கைக் கண்டாள்.',
        '0.2': 'பணிவுடன் நின்ற அவ்வானரச் சிறந்தோனைக் கண்டு மைதிலி பெருவியப்புற்றுச் சிந்தித்தாள்.',
        '0.3': '“ஐயோ, இந்த வானர உயிர் அச்சந்தருவது, அணுகுதற்கரியது!” இதைப் பார்ப்பதே கடினம் என்று எண்ணி அவள் மீண்டும் மயங்கினாள்.',
        '0.4': 'அச்சத்தால் மயங்கிய சீதை இரக்கமாகப் பெரிதும் புலம்பினாள்; துயருற்ற அவ்வழகி “ஹா ராமா, ராமா! ஹா லக்ஷ்மணா!” என்று அழைத்தாள்.',
        '0.5': 'கற்புடைய சீதை திடீரென்று மெல்லிய குரலில் அழுதாள். பின்னர் பணிவுடன் அருகில் வந்த அவ்வானரச் சிறந்தோனைக் கண்டு, “இது கனவு” என்று அழகி மைதிலி எண்ணினாள்.',
        '0.6': 'அவனை நோக்கிய அவள், அகன்று வளைந்த முகமுடைய, வானர அரசனின் ஆணைப்படி நடப்பவனான, பொன்னிற வானரர்களில் சிறந்தவனான, பெருமதிப்புக்குரிய, அறிவாளிகளில் தலைசிறந்த வாயுமைந்தனைக் கண்டாள்.',
        '0.7': 'அவனைக் கண்டதுமே சீதை மிகவும் வருந்தி உயிரற்றவள் போலானாள்; நெடுநேரத்துக்குப் பின் உணர்வு பெற்ற அந்த அகன்ற கண்ணாள் இவ்வாறு எண்ணினாள்:',
        '0.8': '“இன்று நான் தீய கனவு கண்டேன் — சாஸ்திரங்கள் விலக்கிய குரங்கை. ராமனுக்கும் லக்ஷ்மணனுக்கும் என் தந்தை ஜனக மன்னனுக்கும் நலம் உண்டாகட்டும்.',
        '0.9': '“ஆனால் இது கனவல்ல; துயரத்தாலும் வேதனையாலும் வருந்தும் எனக்கு உறக்கமே இல்லை; முழுமதி முகத்தானைப் பிரிந்த எனக்கு இன்பமே இல்லை.',
        '0.10': '“எப்போதும் ‘ராமா, ராமா’ என்று மனதில் எண்ணி, வாயால் அவனையே சொல்லும் நான், அவனுக்கு ஏற்ற, அவனைப் பற்றிய கதையையே காண்கிறேன், கேட்கிறேன்.',
        '0.11': '“இன்று அவன் மீதான காதலால் வருந்தி, என் உணர்வுகள் அனைத்தும் அவனிடமே சென்று, எப்போதும் அவனையே எண்ணுவதால் அவ்வாறே காண்கிறேன், கேட்கிறேன்.',
        '0.12': '“இது என் மனவிருப்பமாக இருக்கலாம் என்று எண்ணுகிறேன்; ஆயினும் அறிவால் ஆராய்கிறேன்: மனவிருப்பத்துக்கு உருவமில்லை, ஆனால் தெளிவான உருவுடைய இவன் என்னுடன் பேசுகிறான்; இதற்குக் காரணம் என்ன?',
        '0.13': '“வாக்கின் தலைவன் பிருஹஸ்பதிக்கும், வஜ்ரம் ஏந்திய இந்திரனுக்கும், சுயம்பு பிரம்மனுக்கும், அக்னிக்கும் வணக்கம்! இவ்வனவாசி என் முன் சொன்னது அப்படியே உண்மையாகட்டும், வேறாகாமல் இருக்கட்டும்.”',
        '0.14': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் முப்பத்திரண்டாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-33': {
      verses: {
        '0.0': 'பவளம் போன்ற முகமுடைய அவன் அம்மரத்திலிருந்து இறங்கி, பணிவான தோற்றத்துடன் தாழ்மையாக அருகில் வந்து வணங்கி,',
        '0.1': 'பேரொளி கொண்ட வாயுமைந்தன் ஹனுமான் தலைமேல் கைகூப்பிச் சீதையிடம் இனிய குரலில் கூறினான்:',
        '0.2': '“தாமரை இதழ் போன்ற கண்ணாளே, அழுக்கடைந்த பட்டாடை உடுத்து மரக்கிளையைப் பற்றி நிற்கும் குற்றமற்றவளே, நீ யார்?',
        '0.3': '“வெண்தாமரை இதழ்களிலிருந்து சிதறும் நீர் போல உன் கண்களிலிருந்து துயரக் கண்ணீர் ஏன் வழிகிறது?',
        '0.4': '“தேவர், அசுரர், நாகர், கந்தர்வர், அரக்கர், யக்ஷர், கின்னரர் — இவர்களுள் நீ யார், அழகியே?',
        '0.5': '“அழகிய முகத்தாளே, நீ ருத்திரர்களிலோ மருத்துக்களிலோ வசுக்களிலோ ஒருத்தியா? எனக்கு நீ தெய்வமாகத் தோன்றுகிறாய்.',
        '0.6': '“சந்திரனைப் பிரிந்து தேவருலகிலிருந்து வீழ்ந்த, விண்மீன்களில் சிறந்த, எல்லாக் குணங்களிலும் மேலான ரோகிணியா நீ?',
        '0.7': '“அல்லது கரிய கண்ணாளே, சினத்தாலோ மயக்கத்தாலோ கணவன் வசிஷ்டரைச் சினமூட்டிய மங்கலமான அருந்ததியா நீ?',
        '0.8': '“மெல்லிடையாளே, இவ்வுலகிலிருந்து மறுவுலகம் சென்ற உன் எந்த மகனுக்காக, தந்தைக்காக, உடன்பிறந்தவனுக்காக அல்லது கணவனுக்காக நீ வருந்துகிறாய்?',
        '0.9': '“உன் அழுகையாலும், நெடுமூச்சாலும், தரையைத் தொடுவதாலும் நீ தேவி அல்லள் என்று எண்ணுகிறேன்; அரசனின் பெயரை நீ நினைவுகூர்வதாலும்,',
        '0.10': '“உன்னிடம் நான் காணும் குறிகளாலும் இலக்கணங்களாலும் நீ ஓர் அரசனின் பட்டத்தரசி, அரசன் மகள் என்று எனக்குப் படுகிறது.',
        '0.11': '“ராவணனால் ஜனஸ்தானத்திலிருந்து வலிந்து கவரப்பட்ட சீதை நீயானால் — உனக்கு நலம் உண்டாகட்டும் — கேட்கும் எனக்கு அதைச் சொல்.',
        '0.12': '“உன் துயரமும், மனிதருக்கு மேலான அழகும், தவக்கோலமும் கொண்டு பார்த்தால் நீ நிச்சயம் ராமனின் பட்டத்தரசியே.”',
        '0.13': 'அவன் சொற்களைக் கேட்டு, ராமனின் புகழ்ச்சியால் மகிழ்ந்த வைதேகி மரத்தின் மேலிருந்த ஹனுமானிடம் கூறினாள்:',
        '0.14': '“பூமியிலுள்ள அரசச் சிங்கங்களில் முதன்மையானவனும், தன்னை அறிந்தவனும், பகைவர் படையை அழிப்பவனுமான தசரதனின் மருமகள் நான்.',
        '0.15': '“விதேக நாட்டு மகாத்மா ஜனகனின் மகள் நான்; சீதை என்பது என் பெயர்; அறிவுடைய ராமனின் மனைவி நான்.',
        '0.16': '“பன்னிரண்டு ஆண்டுகள் நான் அங்கே ராகவனின் இல்லத்தில் மனித இன்பங்களை அனுபவித்து, எல்லா விருப்பங்களும் நிறைவேறி வாழ்ந்தேன்.',
        '0.17': '“பின்பு பதின்மூன்றாம் ஆண்டில் அரசன் குருமார்களுடன் சேர்ந்து இக்ஷ்வாகு குலக் கொழுந்துக்கு முடிசூட்ட முனைந்தான்.',
        '0.18': '“ராகவனின் முடிசூட்டு விழாவுக்கு ஏற்பாடுகள் நடக்கும்போது கைகேயி தன் கணவனிடம் இவ்வாறு சொன்னாள்:',
        '0.19': '“‘நான் நாள்தோறும் உணவு உண்ணவும் மாட்டேன், நீர் அருந்தவும் மாட்டேன்; ராமனுக்கு முடிசூட்டினால் இதுவே என் உயிரின் முடிவு.',
        '0.20': '“‘அரசர்களில் சிறந்தவனே, அன்பால் நீ எனக்குக் கொடுத்த வாக்கு பொய்யாகக் கூடாதென்றால், ராகவன் காட்டுக்குச் செல்லட்டும்.’',
        '0.21': '“வாய்மை தவறாத அவ்வரசன் அரசிக்குக் கொடுத்த வரங்களை நினைத்து, கைகேயியின் கொடிய, இனிமையற்ற சொற்களைக் கேட்டு மயங்கினான்.',
        '0.22': '“அப்போது வாய்மை அறத்தில் நிலைத்த அம்முதிய அரசன் அழுதுகொண்டே புகழுடைய மூத்த மகனிடம் அரசைக் கேட்டான்.',
        '0.23': '“அச்சீர்மிகு வீரன் தந்தையின் சொல்லை முடிசூட்டை விட இனியதாக முதலில் மனதால் ஏற்று, பின்பு வாயால் ஒப்புக்கொண்டான்.',
        '0.24': '“உண்மையான வீரமுடைய ராமன் உயிருக்காகக்கூடக் கொடுப்பானே தவிர வாங்க மாட்டான்; உண்மையே பேசுவான், பொய் பேச மாட்டான்.',
        '0.25': '“அப்பெரும்புகழாளன் விலையுயர்ந்த மேலாடைகளைக் களைந்து, மனதால் அரசைத் துறந்து, என்னைத் தன் தாயிடம் ஒப்படைத்தான்.',
        '0.26': '“ஆனால் நான் காட்டில் வாழ்பவளாக அவனுக்கு முன்னதாகவே விரைந்து புறப்பட்டேன்; அவனில்லாமல் விண்ணுலக வாசமும் எனக்கு இனிக்காது.',
        '0.27': '“அதற்கு முன்பே பெரும்பேறுடையவனும் நண்பர்களை மகிழ்விப்பவனுமான சௌமித்ரி அண்ணனைப் பின்தொடர தர்ப்பையும் மரவுரியும் அணிந்திருந்தான்.',
        '0.28': '“எங்கள் தலைவனின் ஆணையை மதித்து உறுதியான நோன்புடைய நாங்கள் முன்பு கண்டிராத, ஆழ்ந்த தோற்றமுடைய காட்டில் புகுந்தோம்.',
        '0.29': '“அளவற்ற வலிமையுடைய அவன் தண்டகாரண்யத்தில் வசிக்கையில், அவன் மனைவியான என்னைத் தீய அரக்கன் ராவணன் கவர்ந்தான்.',
        '0.30': '“அவன் எனக்கு இரண்டு மாதம் உயிர்வாழும் சலுகை அளித்துள்ளான்; அவ்விரண்டு மாதங்களுக்குப் பின் நான் உயிர் துறப்பேன்.”',
        '0.31': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் முப்பத்துமூன்றாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-34': {
      verses: {
        '0.0': 'துயர் மேல் துயரால் வாடிய அவளுடைய அச்சொற்களைக் கேட்டு வானரச் சிறந்தோன் ஹனுமான் ஆறுதலான பதில் கூறினான்.',
        '0.1': '“தேவி, ராமனின் செய்தியுடன் நான் உன்னிடம் தூதனாக வந்துள்ளேன். வைதேகி, ராமன் நலமாக இருக்கிறான்; அவன் உன் நலத்தை விசாரித்தான்.',
        '0.2': '“பிரம்மாஸ்திரத்தையும் வேதங்களையும் அறிந்த, வேதமறிந்தோரில் சிறந்த தசரதன் மைந்தன் ராமன், தேவி, உன் நலம் கேட்டான்.',
        '0.3': '“உன் கணவனின் அன்புக்குரிய பணியாளனான பேரொளி லக்ஷ்மணனும் துயரத்தால் வெந்து உனக்குத் தலைதாழ்த்தி வணக்கம் தெரிவித்தான்.”',
        '0.4': 'அந்த மனிதச் சிங்கங்கள் இருவரின் நலத்தைக் கேட்டு உடலெல்லாம் சிலிர்த்த தேவி ஹனுமானிடம் கூறினாள்:',
        '0.5': '“‘உயிருடன் இருப்பவனுக்கு நூறு ஆண்டுகள் ஆனாலும் இன்பம் வந்தே தீரும்’ என்னும் இவ்வுலக வழக்கு எனக்கு எவ்வளவு மங்கலமாகத் தோன்றுகிறது!”',
        '0.6': 'அச்சந்திப்பில் அற்புதமான அன்பு தோன்றியது; ஒருவரையொருவர் நம்பி அவ்விருவரும் உரையாடத் தொடங்கினர்.',
        '0.7': 'அவளுடைய அச்சொற்களைக் கேட்டு வாயுமைந்தன் ஹனுமான் துயரால் வெந்த சீதையின் அருகே செல்லத் தொடங்கினான்.',
        '0.8': 'ஹனுமான் அருகில் வர வர, சீதை அவனை ராவணன் என்றே மேலும் மேலும் ஐயுற்றாள்.',
        '0.9': '“ஐயோ, சீ சீ! இவனிடம் இவையனைத்தையும் சொல்லிவிட்டேனே! வேறு உருவம் எடுத்த ராவணனே இவன்.”',
        '0.10': 'துயரால் மெலிந்த குறையற்ற உடலுடையாள் அசோகக் கிளையை விட்டு அங்கேயே தரையில் அமர்ந்தாள்.',
        '0.11': 'அப்போது அந்நீண்ட கையன் ஜனகன் மகளை வணங்கினான்; ஆனால் அச்சத்தால் நடுங்கிய அவள் அவனை மீண்டும் நோக்கவில்லை.',
        '0.12': 'அவன் வணங்குவதைக் கண்டு மதிமுகச் சீதை நெடுமூச்செறிந்து இனிய குரலில் வானரனிடம் கூறினாள்:',
        '0.13': '“இம்மாயையில் புகுந்த மாயாவி ராவணனே நீயாக இருந்து எனக்கு மீண்டும் வேதனை தருகிறாய் என்றால், அது தகாது.',
        '0.14': '“ஜனஸ்தானத்தில் தன் உருவைத் துறந்து துறவி உருவம் எடுத்திருந்த, நான் கண்ட அதே ராவணன் நீதான்.',
        '0.15': '“விரும்பிய உருவெடுக்கும் இரவுலாவியே, உண்ணாநோன்பால் இளைத்த துயருற்ற என்னை மீண்டும் வருத்துகிறாய்; அது தகாது.',
        '0.16': '“அல்லது நான் ஐயுற்றது போல இது இல்லாமலும் இருக்கலாம்; ஏனெனில் உன்னைக் கண்டதும் என் மனதில் மகிழ்ச்சி தோன்றியது.',
        '0.17': '“நீ ராமனின் தூதனாக வந்திருந்தால் உனக்கு நலம் உண்டாகட்டும். வானரச் சிறந்தோனே, உன்னைக் கேட்கிறேன்; ராமனின் கதை எனக்கு இனியது.',
        '0.18': '“வானரனே, என் அன்பு ராமனின் குணங்களைச் சொல்; இனியவனே, வெள்ளம் ஆற்றங்கரையை அரித்துச் செல்வது போல நீ என் உள்ளத்தைக் கவர்கிறாய்.',
        '0.19': '“ஆ, கனவு எவ்வளவு இனிமையானது! நெடுநாள் முன்பு கவரப்பட்ட நான் ராகவன் அனுப்பிய ஒரு வனவாசியைக் காண்கிறேனே!',
        '0.20': '“கனவிலாவது வீர ராகவனை லக்ஷ்மணனுடன் கண்டால் நான் சோர்ந்துபோக மாட்டேன்; ஆனால் கனவும் என்மேல் பொறாமை கொள்கிறது.',
        '0.21': '“இதைக் கனவு என்று நான் எண்ணவில்லை; ஏனெனில் கனவில் குரங்கைக் கண்டால் நன்மை கிட்டாது; ஆனால் எனக்கு நன்மை வந்துள்ளது.',
        '0.22': '“இது என் மனமயக்கமா, வாதக் கோளாறா, பித்தால் தோன்றிய விகாரமா, கானல்நீரா?',
        '0.23': '“அல்லது இது பித்தல்ல, பித்தின் அடையாளமுள்ள மயக்கமும் அல்ல; ஏனெனில் நான் என்னையும் இவ்வனவாசியையும் தெளிவாக அறிகிறேன்.”',
        '0.24': 'இவ்வாறு சீதை பலவாறு சாதக பாதகங்களை எடைபோட்டு, அரக்கர்கள் விரும்பிய உருவெடுப்பவர்கள் என்பதால் அவனை அரக்கர் தலைவனாகவே எண்ணினாள்.',
        '0.25': 'இம்முடிவுக்கு வந்த மெல்லிடையாளான ஜனகன் மகள் சீதை வானரனுக்கு எந்தப் பதிலும் சொல்லவில்லை.',
        '0.26': 'சீதையின் முடிவை உணர்ந்த வாயுமைந்தன் ஹனுமான் அப்போது செவிக்கு இனிய சொற்களால் அவளை மகிழ்வித்துக் கூறினான்:',
        '0.27': '“கதிரவன் போல ஒளியுடையவன், சந்திரன் போல உலகுக்கு இனியவன், வைச்ரவணன் (குபேரன்) போல உலகனைத்துக்கும் அரசன்,',
        '0.28': '“பெரும்புகழ் விஷ்ணுவைப் போல வீரமுடையவன், வாக்கின் தலைவனான தேவனைப் போல வாய்மையும் இனிய சொல்லும் உடையவன்,',
        '0.29': '“அழகன், இனியன், சீர்மிக்கவன், உருவெடுத்த மன்மதன் போன்றவன்; சினம் தகுமிடத்தில் மட்டுமே தாக்குபவன்; உலகில் சிறந்த மகாரதன் —',
        '0.30': '“எந்த மகாத்மாவின் கைகளின் நிழலில் உலகம் அடைக்கலம் பெறுகிறதோ அந்த ராகவனை மான் உருவால் ஆசிரமத்திலிருந்து அகற்றி,',
        '0.31': '“ஆளில்லா இடத்தில் உன்னைக் கவர்ந்தவன் அதன் பலனைக் காண்பான். அவ்வீரன் விரைவில் போரில் ராவணனைக் கொல்வான்,',
        '0.32': '“சினத்தால் விடுக்கப்பட்ட, எரியும் நெருப்புப் போன்ற அம்புகளால். அவன் அனுப்பிய தூதனான நான் இங்கே உன்னிடம் வந்துள்ளேன்.',
        '0.33': '“உன் பிரிவால் வருந்தும் அவன் உன் நலத்தை விசாரித்தான். சுமித்திரையின் மகிழ்ச்சியைப் பெருக்கும் பேரொளி லக்ஷ்மணனும்,',
        '0.34': '“அந்நீண்ட கையன் உன்னை வணங்கி நலம் கேட்டான். தேவி, ராமனின் நண்பனான சுக்ரீவன் என்னும் வானரன்,',
        '0.35': '“வானரத் தலைவர்களின் அரசன், உன் நலம் கேட்டான். சுக்ரீவனுடனும் லக்ஷ்மணனுடனும் ராமன் உன்னை எப்போதும் நினைக்கிறான்.',
        '0.36': '“வைதேகி, அரக்கியரின் பிடியில் சிக்கியும் நற்பேறாக நீ உயிருடன் இருக்கிறாய். விரைவில் நீ ராமனையும் மகாரதன் லக்ஷ்மணனையும் காண்பாய்,',
        '0.37': '“கோடிக்கணக்கான வானரர்களின் நடுவே அளவற்ற வலிமையுடைய சுக்ரீவனையும் காண்பாய். நான் சுக்ரீவனின் அமைச்சன், ஹனுமான் என்னும் வானரன்.',
        '0.38': '“பெருங்கடலைத் தாண்டி, தீய ராவணனின் தலைமேல் கால் வைத்ததுபோல நான் இலங்கை நகரில் புகுந்துள்ளேன்.',
        '0.39': '“என் வீரத்தை நம்பி உன்னைக் காண வந்துள்ளேன். தேவி, நீ எண்ணுவது போன்றவன் நான் அல்லன். இந்த ஐயத்தை விடு; நான் சொல்வதை நம்பு.”',
        '0.40': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் முப்பத்துநான்காம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-35': {
      verses: {
        '0.0': 'வானரச் சிறந்தோனிடமிருந்து அந்த ராமகதையைக் கேட்ட வைதேகி இனிய குரலில் இந்த அமைதியான சொற்களைச் சொன்னாள்:',
        '0.1': '“ராமனுடன் உனக்கு எங்கே தொடர்பு ஏற்பட்டது? லக்ஷ்மணனை நீ எப்படி அறிவாய்? வானரர்களுக்கும் மனிதர்களுக்கும் சந்திப்பு எப்படி நிகழ்ந்தது?',
        '0.2': '“வானரனே, ராமனின் அடையாளங்களையும் லக்ஷ்மணனின் அடையாளங்களையும் மீண்டும் சொல்; அப்போது துயர் என்னை ஆட்கொள்ளாது.',
        '0.3': '“அவனது உடலமைப்பு எத்தகையது, தோற்றம் எத்தகையது? தொடைகள் எப்படி, கைகள் எப்படி? லக்ஷ்மணனைப் பற்றியும் எனக்குச் சொல்.”',
        '0.4': 'வைதேகி இவ்வாறு கேட்கவே வாயுமைந்தன் ஹனுமான் ராமனை உள்ளபடியே விவரிக்கத் தொடங்கினான்.',
        '0.5': '“வைதேகி, தாமரைக் கண்ணாளே, நீ அறிந்திருந்தும் உன் கணவன், லக்ஷ்மணன் இவர்களின் உடலமைப்பைப் பற்றி என்னிடம் கேட்பது நற்பேறே.',
        '0.6': '“அகன்ற கண்ணாளே, நான் கவனித்த ராமனின், லக்ஷ்மணனின் அடையாளங்களைச் சொல்கிறேன், கேள்.',
        '0.7': '“ஜனகன் மகளே, ராமன் தாமரை இதழ் போன்ற கண்களும் முழுமதி போன்ற முகமும் உடையவன்; பிறப்பிலேயே அழகும் கனிவும் கொண்டவன்.',
        '0.8': '“ஒளியில் கதிரவன் போன்றவன், பொறுமையில் பூமிக்கு நிகரானவன், அறிவில் பிருஹஸ்பதிக்கு இணையானவன், புகழில் இந்திரன் போன்றவன்.',
        '0.9': '“அவன் உயிருலகைக் காப்பவன், தன்னவரைக் காப்பவன், தன் ஒழுக்கத்தையும் அறத்தையும் காப்பவன், பகைவரை வாட்டுபவன்.',
        '0.10': '“அழகியே, ராமன் உலகையும் நான்கு வர்ணங்களையும் காப்பவன்; உலக வரம்புகளை அமைப்பவனும் கடைப்பிடிக்கச் செய்பவனும் அவனே.',
        '0.11': '“ஒளிமிக்கவன், மிகவும் போற்றப்படுபவன், பிரம்மசரிய நோன்பில் நிலைத்தவன்; நல்லோரின் உதவியை அறிந்தவன், செயல்களை நடத்தும் முறையை அறிந்தவன்.',
        '0.12': '“அரசியல் நெறியில் பயிற்சி பெற்றவன், அந்தணர்களைப் போற்றுபவன், அறிவுடையவன், நல்லொழுக்கம் நிறைந்தவன், பணிவுடையவன், பகைவரை வாட்டுபவன்.',
        '0.13': '“யஜுர்வேதத்தில் பயிற்சி பெற்றவன், வேதமறிந்தோரால் போற்றப்படுபவன்; வில்வித்தையிலும் வேதத்திலும் வேதாங்கங்களிலும் தேர்ந்தவன்.',
        '0.14': '“அகன்ற தோள்கள், நீண்ட கைகள், சங்கு போன்ற கழுத்து, அழகிய முகம், சதையால் மூடிய காறையெலும்பு, சற்றுச் சிவந்த அழகிய கண்கள் உடையவன் — மக்களிடம் ராமன் எனப் புகழ்பெற்றவன்.',
        '0.15': '“அவனது குரல் துந்துபி போல முழங்கும்; நிறம் மினுமினுப்பானது; வீரமிக்கவன்; ஒத்த அளவுள்ள, நன்கு அமைந்த உறுப்புகள் உடையவன்; கருநிறத்தவன்.',
        '0.16': '“அவன் உடலின் மூன்று பகுதிகளில் உறுதியானவன், மூன்றில் நீண்டவன், மூன்றில் சமமானவன், மூன்றில் உயர்ந்தவன், மூன்றில் செம்மை நிறமுடையவன், மூன்றில் மினுமினுப்பானவன், மூன்றில் எப்போதும் ஆழமானவன்.',
        '0.17': '“மூன்று மடிப்புகள் உடையவன், மூன்று இடங்களில் தாழ்ந்தவன், நான்கில் குட்டையானவன், தலையில் மூன்று சுழிகள் உடையவன்; கட்டைவிரலில் நான்கு ரேகைகள், நெற்றியில் நான்கு ரேகைகள், நான்கு முழ உயரம், நான்கு பகுதிகளில் சமமானவன்.',
        '0.18': '“அவனது பதினான்கு இணை உறுப்புகள் சமமானவை; நான்கு கோரைப்பற்கள் உடையவன், நான்கு வகை நடை உடையவன்; பெரிய இதழ், தாடை, மூக்கு; ஐந்தில் மினுமினுப்பானவன், எட்டு நீண்ட உறுப்புகள் உடையவன்.',
        '0.19': '“ராகவனுக்குத் தாமரை போன்ற பத்து உறுப்புகளும் பெரிய பத்து உறுப்புகளும் உள்ளன; மூன்றால் (ஒளி, புகழ், சீர்) நிறைந்தவன், இரண்டு வெண்மையான உறுப்புகள் உடையவன், ஆறில் உயர்ந்தவன், ஒன்பதில் நுண்மையானவன், மூன்றால் எங்கும் பரவியவன்.',
        '0.20': '“உண்மையிலும் அறத்திலும் ஈடுபாடுடையவன், சீர்மிக்கவன், மக்களை அரவணைப்பதிலும் அருள்வதிலும் விருப்பமுடையவன், இடம் காலம் அறிந்தவன், உலகனைவரிடமும் இனிமையாகப் பேசுபவன்.',
        '0.21': '“அவனுடைய மாற்றாந்தாய் மகனான தம்பி சௌமித்ரி அளவற்ற ஒளியுடையவன்; அன்பிலும் உருவிலும் குணங்களிலும் அவனைப் போன்றவனே.',
        '0.22': '“அவன் பொன்னிற ஒளியுடைய சீர்மிக்கவன்; பெரும்புகழ் ராமன் கருநிறத்தவன். உன்னைக் காண்பதையே திருவிழாவாகக் கருதும் அம்மனிதப் புலிகள் இருவரும்,',
        '0.23': '“உலகம் முழுவதும் தேடிக்கொண்டு எங்களைச் சந்தித்தனர்; உன்னையே தேடிப் பூமியில் திரிந்துகொண்டு,',
        '0.24': '“அண்ணனால் பதவியிழந்த வானரத் தலைவனைப் பல மரங்கள் அடர்ந்த ரிஷ்யமூகத்தின் அடிவாரத்தில் கண்டனர் —',
        '0.25': '“அண்ணனின் அச்சத்தால் வருந்தி அமர்ந்திருந்த காண இனிய சுக்ரீவனை. வாக்குத் தவறாத அவ்வானர அரசன் சுக்ரீவனுக்கு நாங்கள்,',
        '0.26': '“அண்ணனால் அரசிழந்த அவனுக்குப் பணிவிடை செய்து வந்தோம். அப்போது மரவுரி அணிந்து, கைகளில் சிறந்த விற்களை ஏந்திய அவ்விருவரும்,',
        '0.27': '“ரிஷ்யமூக மலையின் அழகிய இடத்துக்கு வந்தனர். வில்லேந்திய அம்மனிதப் புலிகள் இருவரையும் கண்டு அவ்வானரச் சிறந்தோன்,',
        '0.28': '“அச்சத்தால் கலங்கி அம்மலையின் உச்சிக்குத் தாவினான். பின்பு அவ்வுச்சியில் நின்ற வானர அரசன்,',
        '0.29': '“அவர்களிடம் என்னையே விரைந்து அனுப்பினான். சுக்ரீவனின் சொல்லின்படி நான் வல்லமையுடைய அம்மனிதப் புலிகள் இருவரிடமும்,',
        '0.30': '“உருவும் நல்லிலக்கணமும் நிறைந்த அவர்களிடம் கைகூப்பிச் சென்றேன். என்னிடமிருந்து உண்மையை அறிந்த அவர்கள் அன்பு கொண்டனர்.',
        '0.31': '“அவ்விரு மனிதச் சிறந்தோரையும் என் முதுகில் ஏற்றி அவ்விடத்துக்குக் கொண்டுசென்று மகாத்மா சுக்ரீவனுக்கு உள்ளபடியே அறிமுகம் செய்தேன்.',
        '0.32': '“அவர்களின் உரையாடலால் பேரன்பு உண்டானது. அங்கே புகழ்பெற்ற அவ்வானர அரசனும் மனித அரசனும்,',
        '0.33': '“முன்பு நடந்த கதையைச் சொல்லி ஒருவரையொருவர் தேற்றிக்கொண்டனர். பின்பு லக்ஷ்மணனின் அண்ணன் சுக்ரீவனைத் தேற்றினான்,',
        '0.34': '“பெருவலிமையுடைய அண்ணன் வாலியால் ஒரு பெண்ணின் பொருட்டுத் துரத்தப்பட்ட அவனை. பின்பு சலிப்பின்றிச் செயல்புரியும் ராமனுக்கு உன்னை இழந்ததால் ஏற்பட்ட துயரத்தை',
        '0.35': '“லக்ஷ்மணன் வானர அரசன் சுக்ரீவனுக்குத் தெரிவித்தான். லக்ஷ்மணன் சொன்ன சொற்களைக் கேட்டு அவ்வானர அரசன்',
        '0.36': '“கிரகணம் பிடித்த கதிரவன் போல முற்றிலும் ஒளியிழந்தான். பின்பு அரக்கனால் கவரப்படும்போது நீ கீழே போட்ட, உன் உடலை அழகுசெய்த',
        '0.37': '“அணிகலன்களின் தொகுப்புகள் தரையில் விழுந்தனவோ, அவை அனைத்தையும் வானரக் குழுத் தலைவர்கள் ராமனிடம் கொண்டுவந்து,',
        '0.38': '“மகிழ்வுடன் காட்டினர்; ஆனால் நீ எங்கே சென்றாய் என்பது அவர்களுக்குத் தெரியவில்லை. ராமனிடம் கொடுக்கப்பட்ட அவ்வணிகலன்களை நானே சேகரித்திருந்தேன்,',
        '0.39': '“அவை ஒலித்துக்கொண்டு சிதறி விழுந்திருந்தன. அவன் உணர்விழந்தபோது, அழகிய அவற்றை மடியில் வைத்துக்கொண்டு பலவாறாக,',
        '0.40': '“தேவன் போல் ஒளிரும் அந்தப் பிரபு புலம்பினான்; அவற்றைப் பார்த்து, அழுது, மீண்டும் மீண்டும் சோர்ந்து,',
        '0.41': '“அவை தசரதன் மைந்தனிடம் துயர நெருப்பை மூட்டின.',
        '0.42': '“துயருற்ற அம்மகாத்மா நெடுநேரம் வீழ்ந்து கிடந்தான்; நானும் பலவகைச் சொற்களால் சிரமப்பட்டு அவனை மீண்டும் எழுப்பினேன்.',
        '0.43': '“விலையுயர்ந்த அவ்வணிகலன்களைப் பார்த்து, மீண்டும் மீண்டும் காட்டி, ராகவன் சௌமித்ரியுடன் அவற்றைச் சுக்ரீவனிடம் ஒப்படைத்தான்.',
        '0.44': '“உத்தமியே, உன்னைக் காணாமல் ராகவன், எரியும் பெருநெருப்புடைய எரிமலை போல எப்போதும் வெந்துகொண்டிருக்கிறான்.',
        '0.45': '“உன் பொருட்டு உறக்கமின்மை, துயர், கவலை ஆகியவை, நெருப்புகள் வேள்விச்சாலையைச் சுடுவது போல மகாத்மா ராகவனை வாட்டுகின்றன.',
        '0.46': '“பெரும் நிலநடுக்கத்தால் பெரிய மலை அசைவது போல, உன்னைக் காணாத துயரால் ராகவன் நடுங்குகிறான்.',
        '0.47': '“இளவரசியே, அழகிய காடுகளிலும் ஆறுகளிலும் அருவிகளிலும் திரிந்தாலும் உன்னைக் காணாமல் அவனுக்கு எந்த இன்பமும் கிட்டவில்லை.',
        '0.48': '“ஜனகன் மகளே, அந்த மனிதப் புலி ராகவன் நண்பர், உறவினருடன் ராவணனைக் கொன்று விரைவில் உன்னை அடைவான்.',
        '0.49': '“அப்போது ராமனும் சுக்ரீவனும் சேர்ந்து வாலியைக் கொல்வதற்கும் உன்னைத் தேடுவதற்கும் உடன்படிக்கை செய்தனர்.',
        '0.50': '“பின்னர் அவ்விரு வீர இளவரசர்களும் கிஷ்கிந்தைக்குச் சென்றனர்; வானர அரசன் வாலி போரில் வீழ்த்தப்பட்டான்.',
        '0.51': '“போரில் வாலியை விரைவாகக் கொன்று ராமன் சுக்ரீவனைக் கரடி வானரக் கூட்டங்கள் அனைத்துக்கும் தலைவனாக்கினான்.',
        '0.52': '“தேவி, இவ்வாறு ராமனுக்கும் சுக்ரீவனுக்கும் நட்பு உண்டானது. அவர்களின் தூதனாக வந்த ஹனுமான் என்று என்னை அறிவாய்.',
        '0.53': '“தன் அரசை மீண்டும் பெற்ற சுக்ரீவன் தன் பெரும் வானரர்களை அழைத்து, உனக்காக அவ்வலியவர்களைப் பத்துத் திசைகளுக்கும் அனுப்பினான்.',
        '0.54': '“வானர அரசன் சுக்ரீவனின் ஆணைப்படி மலையரசர்கள் போன்ற அவ்வலியவர்கள் எல்லாப் பக்கங்களிலும் பூமியெங்கும் புறப்பட்டனர்.',
        '0.55': '“பின்பு சுக்ரீவனின் ஆணையால் பதற்றமுற்ற அவர்கள் — நாங்களும் பிற வானரர்களும் — பூமி முழுவதும் தேடித் திரிகின்றனர்.',
        '0.56': '“வாலியின் மகனான பெருவலிமையுடைய, சீர்மிக்க, வானரப் புலி அங்கதன் படையின் மூன்றில் ஒரு பகுதியுடன் புறப்பட்டான்.',
        '0.57': '“மலைகளில் சிறந்த விந்தியத்தில் நாங்கள் வழி தவறி, துயரால் சூழப்பட்டு, பல பகலிரவுகள் கழிந்தன.',
        '0.58': '“காரியத்தில் நம்பிக்கை இழந்து, காலக்கெடு கடந்ததாலும், வானர அரசனின் அச்சத்தாலும் நாங்கள் உயிர் துறக்க முனைந்தோம்.',
        '0.59': '“மலைக் கோட்டைகளையும் ஆறுகளையும் அருவிகளையும் தேடியும் தேவியின் தடம் கிடைக்காமல், உயிர் துறக்க முடிவெடுத்தோம்.',
        '0.60': '“அப்போது அம்மலையின் உச்சியில் நாங்கள் சாகும்வரை உண்ணாநோன்பு இருந்தோம். வானரச் சிறந்தோர் அனைவரும் அந்நோன்பில் அமர்ந்திருப்பதைக் கண்டு,',
        '0.61': '“துயரக்கடலில் மூழ்கிய அங்கதன், வைதேகி, உன் இழப்பையும் வாலியின் கொலையையும் எண்ணிப் புலம்பினான்,',
        '0.62': '“எங்கள் உண்ணாநோன்பையும் ஜடாயுவின் மரணத்தையும் எண்ணியும். தலைவனின் ஆணையால் நம்பிக்கையிழந்து சாக விரும்பிய எங்களிடம்,',
        '0.63': '“எங்கள் காரியத்துக்காகவே என்பது போலக் கழுகரசனின் உடன்பிறந்தவனான சம்பாதி என்னும் பெருவலிமையுடைய கழுகரசன் வந்தான்.',
        '0.64': '“தம்பியின் கொலையைக் கேட்டு அவன் சினத்துடன் கூறினான்: ‘என் தம்பியைக் கொன்றது யார்? அவன் எங்கே வீழ்த்தப்பட்டான்?',
        '0.65': '“‘வானரச் சிறந்தோரே, இதை உங்களிடமிருந்து கேட்க விரும்புகிறேன்.’ அங்கதன் ஜனஸ்தானத்தில் நிகழ்ந்த அப்பெரும் கொலையைப் பற்றி அவனுக்குச் சொன்னான்,',
        '0.66': '“கொடிய உருவுடைய அரக்கனால் உன் பொருட்டு நிகழ்ந்ததை உள்ளபடியே. ஜடாயுவின் கொலையைக் கேட்டு வருந்திய அருணனின் மைந்தன்,',
        '0.67': '“அழகியே, நீ ராவணனின் இல்லத்தில் வசிக்கிறாய் என்று சொன்னான். எங்கள் மகிழ்ச்சியைப் பெருக்கிய சம்பாதியின் அச்சொற்களைக் கேட்டு,',
        '0.68': '“அங்கதன் தலைமையில் நாங்கள் அனைவரும் புறப்பட்டோம். விந்தியத்திலிருந்து எழுந்து கடலின் சிறந்த கரையை அடைந்தோம்.',
        '0.69': '“உன்னைக் காணும் ஊக்கத்துடன், மகிழ்ச்சியுடன், உடல்வலிமையுடன் அங்கதன் முதலான வானரர் அனைவரும் கரையின் விளிம்பை அடைந்தனர்.',
        '0.70': '“உன்னைக் காண ஆவலுற்ற அவர்கள் மீண்டும் கொடிய கவலையில் ஆழ்ந்தனர். அப்போது கடலைக் கண்டு சோர்ந்த வானரப் படையைப் பார்த்து நான்,',
        '0.71': '“கடும் அச்சத்தை உதறி நூறு யோஜனை தாண்டினேன். அரக்கர்கள் நிறைந்த இலங்கையில் இரவில் புகுந்தேன்.',
        '0.72': '“நான் ராவணனையும் துயரால் வருந்தும் உன்னையும் கண்டேன். குற்றமற்றவளே, நடந்தவை அனைத்தையும் உள்ளபடியே உனக்குச் சொன்னேன்.',
        '0.73': '“தேவி, என்னுடன் பேசு; நான் தசரதன் மைந்தனின் தூதன். உனக்காக இங்கு வந்த, ராமனின் பணியில் ஈடுபட்ட என்னை,',
        '0.74': '“சுக்ரீவனின் அமைச்சனான வாயுமைந்தன் என்று அறிவாய், தேவி. ஆயுதம் ஏந்துவோரில் சிறந்த உன் காகுத்ஸ்தன் நலமாக இருக்கிறான்.',
        '0.75': '“நல்லிலக்கணமுடைய லக்ஷ்மணன் மூத்தவனுக்குப் பணிவிடை செய்வதில் ஈடுபட்டுள்ளான்; தேவி, வலிமையுடைய உன் கணவனின் நலனில் கருத்துடையவன்.',
        '0.76': '“சுக்ரீவனின் சொல்லின்படி நான் ஒருவனே இங்கு வந்துள்ளேன். துணையின்றி, விரும்பிய உருவெடுத்துத் திரிந்து,',
        '0.77': '“உன் வழியைத் தேடி நான் இத்தென்திசையைக் கடந்துள்ளேன். உன் இழப்பை எண்ணி வருந்தும் வானரப் படைகளின் வேதனையை நற்பேறாக நான்,',
        '0.78': '“உன்னைக் கண்டடைந்த செய்தியால் நீக்குவேன். நற்பேறாக நான் இங்கே கடலைத் தாண்டியது வீணாகவில்லை.',
        '0.79': '“தேவி, உன்னைக் கண்ட இப்புகழை நான் பெறுவேன்; பெருவீரன் ராகவனும் விரைவில் உன்னை அடைவான்,',
        '0.80': '“மைந்தர், உறவினருடன் அரக்கர் தலைவன் ராவணனைக் கொன்று. வைதேகி, மலைகளில் சிறந்த மால்யவான் என்னும் மலை உள்ளது.',
        '0.81': '“அங்கிருந்து கேசரி என்னும் வானரன் கோகர்ண மலைக்குச் சென்றான்; என் தந்தையான அப்பெரும் வானரன் தேவமுனிவர்களின் ஆணைப்படி கடலின் புனிதத் தீர்த்தத்தில் சம்பசாதனனைக் கொன்றான்.',
        '0.82': '“மைதிலி, அவ்வானரனின் மனைவியிடம் வாயுவால் நான் பிறந்தேன்; என் செயலாலேயே உலகில் ஹனுமான் எனப் புகழ்பெற்றேன்.',
        '0.83': '“வைதேகி, உனக்கு நம்பிக்கை உண்டாகவே உன் கணவனின் குணங்களைச் சொன்னேன். தேவி, ராகவன் விரைவில் உன்னை இங்கிருந்து நிச்சயம் அழைத்துச் செல்வான்.”',
        '0.84': 'இவ்வாறு பொருத்தமான காரணங்களாலும் அடையாளங்களாலும் நம்பிக்கை பெற்ற, துயரால் மெலிந்த சீதை அவனைத் தூதன் என்று உணர்ந்தாள்.',
        '0.85': 'ஜானகி அளவற்ற மகிழ்ச்சியடைந்து, களிப்பால் வளைந்த இமைகளுடைய கண்களிலிருந்து ஆனந்தக் கண்ணீர் சொரிந்தாள்.',
        '0.86': 'சிவப்பும் வெண்மையும் கலந்த நீண்ட கண்களுடைய அவ்வகன்ற கண்ணாளின் அழகிய முகம் ராகுவிடமிருந்து விடுபட்ட சந்திரன் போல் ஒளிர்ந்தது.',
        '0.87': 'அவன் வேறு யாருமல்லன், வானரன் ஹனுமானே என்று அவள் தெளிவாக நம்பினாள். அப்போது ஹனுமான் காண இனியவளிடம் மேலும் கூறினான்:',
        '0.88': '“மைதிலி, இவையனைத்தையும் உனக்குச் சொன்னேன்; ஆறுதல் கொள். நான் என்ன செய்ய வேண்டும்? உனக்கு எது விருப்பம்? நான் திரும்பிச் செல்வேன்.”',
        '0.89': '“மாமுனிவர்களின் தூண்டுதலால் அவ்வானர வீரன் போரில் சம்பசாதன அசுரனைக் கொன்ற பின், மைதிலி, வாயுவால் நான் பிறந்தேன்; வல்லமையில் அவனுக்கு நிகரான வானரன் நான்.”',
        '0.90': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் முப்பத்தைந்தாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-36': {
      verses: {
        '0.0': 'சீதைக்கு நம்பிக்கை ஊட்டுவதற்காகப் பேரொளி கொண்ட வாயுமைந்தன் ஹனுமான் மீண்டும் பணிவான சொற்களைக் கூறினான்:',
        '0.1': '“பெரும்பேறுடையவளே, நான் வானரன், அறிவுடைய ராமனின் தூதன். தேவி, ராமனின் பெயர் பொறித்த இந்த மோதிரத்தைப் பார்.',
        '0.2': '“உன் நம்பிக்கைக்காக அம்மகாத்மா கொடுத்தனுப்பியதைக் கொண்டுவந்தேன். ஆறுதல் கொள், உனக்கு நலம் உண்டாகட்டும்; உன் துயரத்தின் பலன் தீர்ந்துவிட்டது.”',
        '0.3': 'கணவனின் கையை அலங்கரித்த அவ்வணியைப் பெற்று நோக்கிய ஜானகி, கணவனே வந்தது போல மகிழ்ந்தாள்.',
        '0.4': 'சிவப்பும் வெண்மையும் கலந்த நீண்ட கண்களுடைய அவளது அழகிய முகம் ராகுவிடமிருந்து விடுபட்ட சந்திரன் போல மகிழ்ச்சியால் மலர்ந்தது.',
        '0.5': 'பின்பு கணவனின் செய்தியால் மகிழ்ந்த நாணமுடைய அவ்விளம்பெண் மனம் நிறைந்து பெரும் வானரனைப் பாராட்டிப் புகழ்ந்தாள்.',
        '0.6': '“வானரச் சிறந்தோனே, நீ வீரன், வல்லவன், அறிஞன்; ஏனெனில் நீ ஒருவனே இவ்வரக்கர் இருப்பிடத்தை வென்று புகுந்தாய்.',
        '0.7': '“நூறு யோஜனை அகலமுள்ள, முதலைகளின் உறைவிடமான கடலை, வீரத்தால் போற்றத்தக்க நீ கடக்கும்போது பசுவின் குளம்படிச் சுவடு போலாக்கினாய்.',
        '0.8': '“வானரச் சிறந்தோனே, உன்னைச் சாதாரண வானரன் என்று நான் எண்ணவில்லை; ஏனெனில் உனக்கு ராவணனிடமும் அச்சமோ பதற்றமோ இல்லை.',
        '0.9': '“வானரச் சிறந்தோனே, தன்னை அறிந்த ராமன் உன்னை அனுப்பியிருந்தால், என்னுடன் பேச நீ தகுதியுடையவன்.',
        '0.10': '“வெல்லவியலாத ராமன் சோதிக்காமல், வீரத்தை அறியாமல், அதிலும் குறிப்பாக என்னிடம், எவரையும் அனுப்ப மாட்டான்.',
        '0.11': '“நற்பேறாக அறவோனும் வாக்குத் தவறாதவனுமான ராமன் நலமாக இருக்கிறான்; சுமித்திரையின் மகிழ்ச்சியைப் பெருக்கும் பேரொளி லக்ஷ்மணனும் நலமே.',
        '0.12': '“காகுத்ஸ்தன் நலமாக இருந்தால், ஊழிக்கால நெருப்புப் போலச் சினந்து கடல் சூழ்ந்த பூமியை ஏன் எரிக்கவில்லை?',
        '0.13': '“அல்லது அவ்விருவரும் தேவர்களையும் அடக்க வல்லவர்கள்; என் துயரங்களுக்குத்தான் இன்னும் முடிவு வரவில்லை என்று எண்ணுகிறேன்.',
        '0.14': '“ராமன் வருந்தவில்லையே? வேதனைப்படவில்லையே? அப்புருஷோத்தமன் அடுத்துச் செய்ய வேண்டியவற்றைச் செய்கிறான் அல்லவா?',
        '0.15': '“அவன் துவண்டோ பதறியோ, செயல்களில் குழம்பியோ இல்லையே? அரசன் மகன் ஆண்மைக்குரிய முயற்சிகளைச் செய்கிறான் அல்லவா?',
        '0.16': '“வெற்றியை நாடும், நண்பர்களுக்கு நல்லவனான அப்பகைவரை வாட்டுபவன், நண்பர்களிடமும் பகைவர்களிடமும் இருவகை, மூவகை உபாயங்களைக் கையாள்கிறான் அல்லவா?',
        '0.17': '“அவன் நண்பர்களைப் பெறுகிறானா? பகைவர்களும் அவனை நாடி வருகிறார்களா? அவனுக்கு நல்ல நண்பர்கள் உள்ளனரா? நண்பர்கள் அவனை மதிக்கிறார்களா?',
        '0.18': '“இளவரசன் தேவர்களின் அருளை வேண்டுகிறானா? முயற்சியையும் விதியையும் இரண்டையும் சார்ந்திருக்கிறானா?',
        '0.19': '“நான் பிரிந்திருப்பதால் ராகவனுக்கு என்மேல் அன்பு குறையவில்லையே? ராகவன் இத்துன்பத்திலிருந்து என்னை விடுவிப்பானா?',
        '0.20': '“எப்போதும் இன்பத்துக்குப் பழகிய, துன்பத்துக்குப் பழகாத ராமன் இப்பெருந்துயரை அடைந்து சோர்ந்துவிடவில்லையே?',
        '0.21': '“கௌசல்யை, சுமித்திரை, பரதன் ஆகியோரின் நலச் செய்தியை அவன் அடிக்கடி கேட்கிறானா?',
        '0.22': '“மதிப்புக்குரிய ராகவன் என் பொருட்டு வருந்துகிறானா? ராமனின் மனம் வேறெங்கும் செல்லவில்லையே? அவன் என்னைக் கரையேற்றுவானா?',
        '0.23': '“உடன்பிறந்தவனிடம் அன்புடைய பரதன் என் பொருட்டு அமைச்சர்களால் காக்கப்படும் அச்சந்தரும் அக்ஷௌஹிணிப் படையை அனுப்புவானா?',
        '0.24': '“வானரத் தலைவனான சீர்மிக்க சுக்ரீவன், பற்களையும் நகங்களையும் ஆயுதமாகக் கொண்ட வீர வானரர்கள் சூழ என் பொருட்டு வருவானா?',
        '0.25': '“சுமித்திரையின் மகிழ்ச்சியைப் பெருக்கும், அஸ்திரம் அறிந்த வீர லக்ஷ்மணன் அம்புவலையால் அரக்கர்களைச் சிதறடிப்பானா?',
        '0.26': '“ராமன் கொடிய அஸ்திரத்தால் போரில் கொன்ற ராவணனை அவன் நண்பர்களுடன் சிறிது காலத்தில் நான் காண்பேனா?',
        '0.27': '“பொன்னிறமும் தாமரை மணமும் கொண்ட அவன் முகம் நானில்லாமல் துயரால் வாடி, நீர் வற்றியபோது வெயிலில் தாமரை போல உலர்ந்துவிடவில்லையே?',
        '0.28': '“அறத்தின் பொருட்டுத் தன் அரசைத் துறந்து, என்னையும் கால்நடையாகக் காட்டுக்கு அழைத்துச் சென்றபோது அச்சமோ துயரோ இல்லாதிருந்த அவன், உள்ளத்தில் துணிவைக் காத்துள்ளானா?',
        '0.29': '“அவன் தாயோ தந்தையோ வேறு எவரோ அன்பில் என்னைவிட மேலானவர் அல்லர், எனக்கு நிகரும் அல்லர். தூதனே, என் அன்பனின் செய்தியைக் கேட்கும் வரையே நான் வாழ விரும்புகிறேன்.”',
        '0.30': 'பொருள் நிறைந்த இனிய இச்சொற்களை அவ்வானரச் சிறந்தோனிடம் கூறி, ராமனைப் பற்றிய அவனது இனிய சொற்களை மீண்டும் கேட்க விரும்பி அந்த அழகிய தேவி அமைதியானாள்.',
        '0.31': 'சீதையின் சொற்களைக் கேட்டு அச்சந்தரும் வீரமுடைய மாருதி தலைமேல் கைகூப்பி இவ்வாறு பதில் கூறினான்:',
        '0.32': '“நீ இங்கே இருப்பதைத் தாமரைக் கண்ணன் ராமன் அறியான்; அதனால்தான் இந்திரன் சசியை மீட்டது போல அவன் உன்னை விரைவில் மீட்கவில்லை.',
        '0.33': '“என் சொற்களைக் கேட்டதுமே ராகவன் வானர, கரடிக் கூட்டங்கள் நிறைந்த பெரும்படையை நடத்திக்கொண்டு விரைந்து வருவான்.',
        '0.34': '“கலங்காத கடலை அம்பு வெள்ளத்தால் தடுத்து நிறுத்தி, காகுத்ஸ்தன் இலங்கை நகரை அரக்கர்கள் இல்லாததாக்குவான்.',
        '0.35': '“இடையில் மரணமோ தேவர்களோ பெரும் அசுரர்களோ ராமனின் வழியில் நின்றால், அவன் அவர்களையும் கொல்வான்.',
        '0.36': '“உத்தமியே, உன்னைக் காணாத துயரால் நிறைந்த ராமன், சிங்கத்தால் தாக்கப்பட்ட யானை போல அமைதி பெறவில்லை.',
        '0.37': '“தேவி, மந்தர மலை மீதும், கிழங்குகள் கனிகள் மீதும், மலயம், விந்தியம், மேரு, தர்துரம் ஆகிய மலைகள் மீதும் ஆணையிட்டுச் சொல்கிறேன்,',
        '0.38': '“அழகிய கண்களும், கோவைப்பழம் போன்ற இதழ்களும், அழகிய குண்டலங்களும் உடைய ராமனின் முகத்தை உதித்த முழுமதி போல நீ காண்பாய்.',
        '0.39': '“வைதேகி, விரைவில் பிரஸ்ரவண மலையில் யானையரசனின் முதுகில் அமர்ந்த இந்திரன் போல ராமனை நீ காண்பாய்.',
        '0.40': '“ராகவன் இறைச்சி உண்பதில்லை, தேனும் அருந்துவதில்லை; நாள்தோறும் பகலின் ஐந்தாம் பகுதியில் முறையாகச் சமைத்த காட்டு உணவையே உண்கிறான்.',
        '0.41': '“உள்ளம் முழுதும் உன்னிடம் சென்றிருப்பதால் ராகவன் தன் உடலிலிருந்து ஈக்கள், கொசுக்கள், பூச்சிகள், ஊர்வன ஆகியவற்றையும் விரட்டுவதில்லை.',
        '0.42': '“ராமன் எப்போதும் சிந்தனையில் ஆழ்ந்தவன், எப்போதும் துயரில் மூழ்கியவன்; காதலின் வசப்பட்ட அவன் வேறு எதையும் எண்ணுவதில்லை.',
        '0.43': '“ராமன் எப்போதும் உறக்கமின்றி இருக்கிறான்; அம்மனிதச் சிறந்தோன் உறங்கினாலும் ‘சீதா’ என்னும் இனிய சொல்லை உரைத்துக்கொண்டே விழிக்கிறான்.',
        '0.44': '“கனியையோ மலரையோ பெண்ணின் உள்ளம் கவரும் வேறு எதையோ கண்டால், ‘ஐயோ அன்பே!’ என்று மீண்டும் மீண்டும் பெருமூச்செறிந்து உன்னிடம் பேசுகிறான்.',
        '0.45': '“தேவி, இடைவிடாது வருந்தி, ‘சீதா!’ என்று உன்னையே அழைத்துக்கொண்டு, உறுதியான நோன்புடைய அம்மகாத்மா இளவரசன் உன்னை அடைவதற்காகவே முயல்கிறான்.”',
        '0.46': 'ராமனின் புகழ்ச்சியால் துயர் நீங்கியும், ராமனின் துயரால் அவனுக்கு நிகரான துயருற்ற விதேகன் மகள், இன்னும் சிறிது மேகம் எஞ்சிய சந்திரனுடைய கூதிர்கால இரவு போலானாள்.',
        '0.47': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் முப்பத்தாறாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-37': {
      verses: {
        '0.0': 'அச்சொற்களைக் கேட்டு முழுமதி முகத்தாளான சீதை ஹனுமானிடம் அறமும் பொருளும் நிறைந்த இச்சொற்களைச் சொன்னாள்:',
        '0.1': '“வானரனே, ராமன் வேறு எதையும் எண்ணுவதில்லை என்பதும் துயரில் மூழ்கியுள்ளான் என்பதும் — நீ சொன்னது நஞ்சு கலந்த அமுதம் போல் உள்ளது.',
        '0.2': '“பெரும் செல்வத்திலும் கொடிய துன்பத்திலும் விதி மனிதனைக் கயிற்றால் கட்டியது போல இழுத்துச் செல்கிறது.',
        '0.3': '“வானரச் சிறந்தோனே, உயிர்களுக்கு விதியைத் தவிர்க்க இயலாது; சௌமித்ரியும் நானும் ராமனும் துன்பங்களால் எப்படி மயங்கியுள்ளோம் பார்.',
        '0.4': '“படகு உடைந்து கடலில் நீந்திக் களைத்தவன் போல ராகவன் இத்துயரத்தின் கரையை எப்படி அடைவான்?',
        '0.5': '“அரக்கர்களைக் கொன்று, ராவணனை அழித்து, இலங்கையைச் சிதைத்து என் கணவன் என்னை எப்போது காண்பான்?',
        '0.6': '“விரைந்து வருமாறு அவனிடம் சொல்; இவ்வாண்டுக் கெடு முடியும் வரைதான் என் உயிர் இருக்கும்.',
        '0.7': '“வானரனே, இது பத்தாவது மாதம்; கொடிய ராவணன் எனக்கு விதித்த கெடுவில் இன்னும் இரண்டு மாதங்கள் உள்ளன.',
        '0.8': '“என்னைத் திருப்பி ஒப்படைக்குமாறு அவனது தம்பி விபீஷணன் முயன்று வேண்டினான்; ஆனால் அவன் அதற்கு மனம் வைக்கவில்லை.',
        '0.9': '“என்னைத் திருப்பித் தருவது ராவணனுக்கு உகந்ததாக இல்லை; காலத்தின் பிடியில் சிக்கிய ராவணனை மரணம் போரில் தேடுகிறது.',
        '0.10': '“வானரனே, விபீஷணனின் மூத்த மகளான கலை என்பவள் தன் தாயால் அனுப்பப்பட்டு தானே எனக்கு இதைச் சொன்னாள்.',
        '0.11': '“அவிந்தியன் என்னும் அறிவுடைய, கற்றறிந்த, உறுதியுடைய, நல்லொழுக்கமுள்ள, முதிய, ராவணனால் பெரிதும் மதிக்கப்படும் அரக்கர் தலைவன்,',
        '0.12': '“ராமனால் அரக்கர்களுக்கு அழிவு வரப்போகிறது என்று அவனை எச்சரித்தான்; ஆனால் அத்தீயவன் அவனுடைய நன்மொழியைக் கேட்பதில்லை.',
        '0.13': '“வானரச் சிறந்தோனே, என் கணவன் விரைவில் என்னை அடைவான் என்று நம்புகிறேன்; ஏனெனில் என் உள்ளம் தூயது, அவனிடம் பல குணங்கள் உள்ளன.',
        '0.14': '“வானரனே, ஊக்கம், ஆண்மை, வலிமை, இரக்கம், நன்றியுணர்வு, வீரம், மாட்சி — இவையனைத்தும் ராகவனிடம் உள்ளன.',
        '0.15': '“தம்பியின் துணையின்றி ஜனஸ்தானத்தில் பதினான்காயிரம் அரக்கர்களைக் கொன்றவனுக்கு எந்தப் பகைவன்தான் அஞ்ச மாட்டான்?',
        '0.16': '“அம்மனிதச் சிறந்தோனைத் துன்பங்கள் அசைக்க முடியாது; புலோமன் மகள் இந்திரனின் வல்லமையை அறிவது போல நான் அவன் வல்லமையை அறிவேன்.',
        '0.17': '“வானரனே, அம்புவலைகளைக் கதிர்களாகக் கொண்ட வீர ராமசூரியன், பகை அரக்கர்களாகிய நீரை வற்றச் செய்வான்.”',
        '0.18': 'ராமனுக்காகத் துயரால் மெலிந்து, கண்ணீர் நிறைந்த முகத்துடன் இவ்வாறு பேசிய அவளிடம் வானரன் ஹனுமான் கூறினான்:',
        '0.19': '“என் சொற்களைக் கேட்டதுமே ராகவன் வானரர், கரடிகள் நிறைந்த பெரும்படையை நடத்திக்கொண்டு விரைந்து வருவான்.',
        '0.20': '“அல்லது அரக்கர்கள் உள்ள இவ்விடத்திலிருந்தும் இத்துயரத்திலிருந்தும் இன்றே உன்னை விடுவிப்பேன். குற்றமற்றவளே, என் முதுகில் ஏறு.',
        '0.21': '“உன்னை முதுகில் ஏற்றிக்கொண்டு நான் கடலைக் கடப்பேன்; ராவணனுடன் இலங்கையையே சுமக்கும் வலிமை எனக்கு உண்டு.',
        '0.22': '“மைதிலி, அக்னி வேள்வியில் இட்ட அவியை இந்திரனிடம் சேர்ப்பது போல இன்றே நான் உன்னைப் பிரஸ்ரவணத்தில் உள்ள ராகவனிடம் சேர்ப்பேன்.',
        '0.23': '“வைதேகி, அசுரர்களைக் கொல்ல முனைந்த விஷ்ணுவைப் போல உறுதியுடைய ராகவனை லக்ஷ்மணனுடன் இன்றே நீ காண்பாய்,',
        '0.24': '“உன்னைக் காண ஊக்கமுற்ற, ஆசிரமத்தில் இருக்கும், மலையரசனின் உச்சியில் அமர்ந்த இந்திரன் போன்ற அப்பெருவலியோனை.',
        '0.25': '“தேவி, என் முதுகில் ஏறு; அழகியே, தயங்காதே. சந்திரனுடன் ரோகிணி போல ராமனுடன் சேர நாடு.',
        '0.26': '“‘ரோகிணி போல நீ சந்திரனுடன் சேர்வாய்’ என்று அறிவிப்பது போல என் முதுகில் ஏறி வான்வழியே பெருங்கடலைக் கடப்பாய்.',
        '0.27': '“பெண்ணே, உன்னை இங்கிருந்து சுமந்துகொண்டு நான் புறப்பட்டால், இலங்கைவாசிகள் எவரும் என் வேகத்தைப் பின்தொடர முடியாது.',
        '0.28': '“நான் இங்கே எப்படி வந்தேனோ அப்படியே ஐயமின்றி உன்னை வானில் தூக்கிக்கொண்டு செல்வேன் — பார், வைதேகி.”',
        '0.29': 'வானரச் சிறந்தோனின் அவ்வியத்தகு சொற்களைக் கேட்டு, மகிழ்ச்சியாலும் வியப்பாலும் உடலெல்லாம் சிலிர்த்த மைதிலி ஹனுமானிடம் கூறினாள்:',
        '0.30': '“ஹனுமானே, இவ்வளவு தொலைவு என்னை எப்படிக் கொண்டுசெல்ல நினைக்கிறாய்? வானரக் குழுத் தலைவனே, இது உன் குரங்குத் தன்மையே என்று எண்ணுகிறேன்.',
        '0.31': '“வானரச் சிறந்தோனே, இவ்வளவு சிறிய உடலுடைய நீ என்னை இங்கிருந்து மனித அரசனான என் கணவனிடம் எப்படிக் கொண்டுசெல்ல விரும்புகிறாய்?”',
        '0.32': 'சீதையின் சொற்களைக் கேட்டுச் சீர்மிக்க வாயுமைந்தன் ஹனுமான் இதைத் தனக்கு நேர்ந்த புதிய அவமதிப்பாக எண்ணினான்.',
        '0.33': '“இக்கரிய கண்ணாள் என் வலிமையையோ வல்லமையையோ அறியாள். ஆகவே விருப்பப்படி நான் எடுக்கக்கூடிய உருவத்தை வைதேகி காணட்டும்.”',
        '0.34': 'இவ்வாறு எண்ணி வானரச் சிறந்தோனும் பகைவரை நசுக்குபவனுமான ஹனுமான் அப்போது சீதைக்குத் தன் உண்மை உருவைக் காட்டினான்.',
        '0.35': 'அறிவுடைய அவ்வானரச் சிறந்தோன் அம்மரத்திலிருந்து குதித்து, சீதைக்கு நம்பிக்கை உண்டாக வளரத் தொடங்கினான்.',
        '0.36': 'மேரு, மந்தர மலைகள் போல, எரியும் நெருப்பைப் போல ஒளிர்ந்து அவ்வானரச் சிறந்தோன் சீதையின் முன் நின்றான்.',
        '0.37': 'மலை போன்ற, சிவந்த முகமுடைய, பெருவலிமையுடைய, வஜ்ரம் போன்ற பற்களும் நகங்களும் கொண்ட அச்சந்தரும் வானரன் வைதேகியிடம் கூறினான்:',
        '0.38': '“மலைகள், காடுகள், கோபுரங்கள், மதில்கள், தோரணங்களுடனும் அதன் தலைவனுடனும் இவ்விலங்கையையே தூக்கிச் செல்லும் வலிமை எனக்கு உண்டு.',
        '0.39': '“ஆகவே மனதை உறுதிப்படுத்து; தேவி, தயக்கம் போதும். வைதேகி, ராகவனையும் லக்ஷ்மணனையும் துயரற்றவர்களாக்கு.”',
        '0.40': 'மலை போன்ற அவனைக் கண்டு தாமரை இதழ் போல அகன்ற கண்களுடைய ஜனகன் மகள் வாயுவின் சொந்த மைந்தனிடம் கூறினாள்:',
        '0.41': '“பெரும் வானரனே, உன் வலிமையையும் ஆற்றலையும், காற்றுப் போன்ற வேகத்தையும், நெருப்புப் போன்ற வியத்தகு ஒளியையும் நான் அறிவேன்.',
        '0.42': '“வானரக் குழுத் தலைவனே, அளவற்ற கடலின் அக்கரையிலுள்ள இந்நிலத்துக்கு வேறு எந்தச் சாதாரண உயிர்தான் வர முடியும்?',
        '0.43': '“செல்வதிலும் என்னைக் கொண்டுசெல்வதிலும் உன் வல்லமையை அறிவேன். ஆயினும் காரியம் நிறைவேற விரைவில் நன்கு ஆராய்ந்து பார்க்க வேண்டும்.',
        '0.44': '“ஆனால் வானரச் சிறந்தோனே, உன்னுடன் நான் செல்வது தகாது; காற்றின் வேகத்துக்கு நிகரான உன் வேகம் என்னை மயக்கமடையச் செய்யலாம்.',
        '0.45': '“கடலுக்கு மேலே உயரத்தில் வானில் தொங்கியபடி, நீ மிக வேகமாகச் செல்லும்போது நான் உன் முதுகிலிருந்து விழக்கூடும்.',
        '0.46': '“திமிங்கலங்கள், முதலைகள், மீன்கள் நிறைந்த கடலில் விழுந்து நான் உதவியற்றவளாய் நீர்வாழ் உயிர்களுக்குச் சிறந்த உணவாவேன்.',
        '0.47': '“பகைவரை அழிப்பவனே, உன்னுடன் நான் வர இயலாது; காக்க வேண்டிய பெண் உடனிருந்தால் உனக்கு நிச்சயம் ஆபத்து நேரும்.',
        '0.48': '“என்னைக் கொண்டுசெல்வதைக் கண்டு, தீய ராவணனால் ஏவப்பட்ட கொடிய வீரமுடைய அரக்கர்கள் பின்தொடர்வர்.',
        '0.49': '“சூலங்களும் உலக்கைகளும் கையிலேந்திய அவ்வீரர்களால் சூழப்பட்டு, வீரனே, என்னைச் சுமந்துள்ள நீ ஆபத்தில் சிக்குவாய்.',
        '0.50': '“வானில் ஆயுதமேந்திய பல அரக்கர்கள், நீயோ ஆயுதமின்றி; போரிட்டுக்கொண்டே என்னையும் எப்படிக் காப்பாய்?',
        '0.51': '“வானரச் சிறந்தோனே, கொடுஞ்செயல் புரியும் அவ்வரக்கர்களுடன் நீ போரிடும்போது அச்சத்தால் நான் உன் முதுகிலிருந்து விழக்கூடும்.',
        '0.52': '“அல்லது அச்சந்தரும், பெரிய, வலிமைமிக்க அவ்வரக்கர்கள் போரில் எப்படியோ உன்னை வென்றுவிடக்கூடும், வானரச் சிறந்தோனே.',
        '0.53': '“அல்லது போரிட்டுக்கொண்டு நீ திரும்பும்போது நான் விழக்கூடும்; விழுந்த என்னைப் பாவி அரக்கர்கள் பிடித்துக் கொண்டுசெல்வர்.',
        '0.54': '“அல்லது உன் கைகளிலிருந்து என்னைப் பறிக்கலாம், அல்லது கொல்லவும் செய்யலாம்; ஏனெனில் போரில் வெற்றியும் தோல்வியும் நிச்சயமற்றவை.',
        '0.55': '“அல்லது அரக்கர்களின் மிரட்டலால் நான் இறந்தும் போகலாம்; அப்போது, வானரச் சிறந்தோனே, உன் முயற்சி வீணாகிவிடும்.',
        '0.56': '“அரக்கர் அனைவரையும் கொல்ல நீயும் வல்லவனே எனலாம்; ஆனால் உன்னால் அரக்கர்கள் கொல்லப்பட்டால் ராகவனின் புகழ் குறையும்.',
        '0.57': '“அல்லது அரக்கர்கள் என்னைக் கொண்டுசென்று வானரர்களோ ராகவனோ அறிய முடியாத மறைவிடத்தில் வைத்துவிடலாம்.',
        '0.58': '“அப்போது என் பொருட்டு நீ செய்த இம்முயற்சி பயனற்றதாகும். உன்னுடன் ராமன் இங்கு வருவதில்தான் பெரும் நன்மை உள்ளது.',
        '0.59': '“நீண்ட கையனே, அளவற்ற வலிமையுடைய ராகவனின், அவன் தம்பியரின், உன் அரச குலத்தின் உயிரும் என்னைச் சார்ந்தே உள்ளது.',
        '0.60': '“என் பொருட்டு நம்பிக்கை இழந்து, துயராலும் வேதனையாலும் மெலிந்த அவ்விருவரும் கரடிகள், வானரர்கள் அனைவருடனும் உயிர் துறப்பர்.',
        '0.61': '“மேலும், வானரச் சிறந்தோனே, கணவன் மீதான பக்தியை முன்னிறுத்தி, ராமனைத் தவிர வேறு எவருடைய உடலையும் நான் விருப்பத்துடன் தொட விரும்பேன்.',
        '0.62': '“ராவணனின் உடல் தொடுதல் எனக்கு வலிந்து நேர்ந்தது — வலிமையற்றவளும், துணையற்றவளும், உதவியற்றவளுமான நான் என்ன செய்வேன்?',
        '0.63': '“ராமன் இங்கே அரக்கர்களுடன் தசக்ரீவனைக் கொன்று என்னை இங்கிருந்து அழைத்துச் சென்றால், அதுவே அவனுக்குத் தகுந்தது.',
        '0.64': '“போரில் பகைவரை நசுக்கும் அம்மகாத்மாவின் வீரச்செயல்களை நான் கேட்டும் கண்டும் உள்ளேன்; தேவர், கந்தர்வர், நாகர், அரக்கர் எவரும் போரில் ராமனுக்கு நிகரல்லர்.',
        '0.65': '“வியத்தகு வில்லுடைய, பெருவலிமையுடைய, இந்திரனுக்கு நிகரான வீரமுடைய ராகவனை லக்ஷ்மணனுடன் போரில் கண்டு, காற்றால் மூட்டப்பட்ட நெருப்புப் போல எரியும் அவனை யார்தான் தாங்க முடியும்?',
        '0.66': '“வானரத் தலைவனே, மதங்கொண்ட திசையானை போல நிற்கும், ஊழிக்காலக் கதிரவன் போல அம்புச்சுடர்கள் உடைய, போரில் பகைவரை நசுக்கும் ராகவனை லக்ஷ்மணனுடன் யார்தான் தாங்குவர்?',
        '0.67': '“ஆகவே வானரச் சிறந்தோனே, என் அன்பு ராமனை லக்ஷ்மணனுடனும் குழுத் தலைவர்களுடனும் விரைவில் இங்கே அழைத்து வா; வானர வீரனே, நெடுங்காலமாக ராமனுக்காகத் துயரால் மெலிந்த என்னை மகிழ்விப்பாய்.”',
        '0.68': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் முப்பத்தேழாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-38': {
      verses: {
        '0.0': 'அச்சொற்களால் மகிழ்ந்த, பேச்சில் வல்ல அவ்வானரப் புலி அவற்றைக் கேட்டுச் சீதையிடம் கூறினான்:',
        '0.1': '“காண இனிய தேவி, நீ சொன்னது மிகப் பொருத்தமானது; பெண்ணின் இயல்புக்கும் கற்புடையோரின் அடக்கத்துக்கும் ஏற்றது.',
        '0.2': '“பெண்ணாதலால் நூறு யோஜனை அகலமுள்ள கடலை என்மேல் அமர்ந்து கடக்க நீ இயலாதவள்.',
        '0.3': '“அடக்கமுடைய ஜானகி, ராமனைத் தவிர வேறொருவரைத் தொட எனக்குத் தகாது என்று நீ சொல்லும் இரண்டாவது காரணம்,',
        '0.4': '“தேவி, அம்மகாத்மாவின் மனைவியான உனக்கு இது தகுந்ததே; தேவி, உன்னைத் தவிர வேறு யார் இத்தகைய சொல்லைச் சொல்வார்?',
        '0.5': '“தேவி, நீ செய்தவற்றையும் என் முன் சொன்னவற்றையும் எதையும் விடாமல் காகுத்ஸ்தன் கேட்பான்.',
        '0.6': '“தேவி, பல காரணங்களால், ராமனுக்கு இனியதைச் செய்யும் விருப்பத்தால், அன்பால் கசிந்த மனதுடன் நான் இதைச் சொன்னேன்.',
        '0.7': '“இலங்கையில் புகுவது கடினம் என்பதாலும், பெருங்கடலைக் கடப்பது கடினம் என்பதாலும், என் திறமையாலும் நான் இதைச் சொன்னேன்.',
        '0.8': '“இன்றே உன்னை ரகுநந்தனனுடன் சேர்க்க விரும்பினேன்; ஆழ்ந்த அன்பாலும் பக்தியாலும் அதைச் சொன்னேனே தவிர வேறு காரணத்தால் அல்ல.',
        '0.9': '“குற்றமற்றவளே, என்னுடன் வர உனக்கு மனமில்லையெனில், ராகவன் அடையாளம் காணக்கூடிய ஓர் அடையாளத்தைக் கொடு.”',
        '0.10': 'ஹனுமான் இவ்வாறு கூறவே, தேவமகள் போன்ற சீதை கண்ணீரால் தடுமாறும் சொற்களில் மெல்லக் கூறினாள்:',
        '0.11': '“என் அன்பனிடம் இந்தச் சிறந்த அடையாளத்தைச் சொல்: சித்திரகூட மலையின் அடிவாரத்தில் வடகிழக்குப் பகுதியில்,',
        '0.12': '“கிழங்கு, கனி, நீர் நிறைந்த, சித்தர்கள் வாழும், மந்தாகினிக்கு அருகிலுள்ள அப்பகுதியின் தவசிகள் ஆசிரமத்தில் நான் வசித்தபோது,',
        '0.13': '“பலவகை மலர்களின் மணம் கமழும் அங்கிருந்த சோலைகளில் விளையாடி, நீரில் நனைந்த நீ என் மடியில் அமர்ந்தாய்.',
        '0.14': '“அப்போது இறைச்சி ஆசையுடைய ஒரு காகம் என்னைக் கொத்தியது; நான் மண்கட்டியை எடுத்து அக்காகத்தை விரட்டினேன்.',
        '0.15': '“என்னைக் காயப்படுத்திய அக்காகம் அங்கேயே மறைந்துகொண்டது; உணவை விரும்பிய அப்பலியுண்ணி இறைச்சியை விடவில்லை.',
        '0.16': '“அப்பறவையின் மீது சினந்து நான் இடைக்கச்சையை மேலே இழுக்கையில், ஆடை நழுவுகையில் நீ என்னைக் கண்டாய்.',
        '0.17': '“நீ என்னைப் பார்த்துச் சிரித்தாய்; நான் சினந்து நாணினேன்; உணவாசையுடைய காகத்தால் காயமுற்று உன்னிடம் வந்தேன்.',
        '0.18': '“பின்பு களைத்த நான் அமர்ந்திருந்த உன் மடியில் அமர்ந்தேன்; சினந்தவள் போலிருந்த என்னை மகிழ்ந்த நீ தேற்றினாய்.',
        '0.19': '“நாதா, கண்ணீர் நிறைந்த முகத்துடன் மெல்லக் கண்களைத் துடைத்துக்கொண்டிருந்த, காகத்தால் சினமூட்டப்பட்ட என்னை நீ கண்டாய்.',
        '0.20': '“களைப்பால் நான் ராகவனின் மடியில் நெடுநேரம் உறங்கினேன்; மாறி மாறி பரதனின் அண்ணனும் என் மடியில் உறங்கினான்.',
        '0.21': '“அப்போது அக்காகம் மீண்டும் அங்கு வந்தது; உறக்கத்திலிருந்து விழித்து ராகவனின் மடியிலிருந்து நான் எழுந்தபோது, அக்காகம் திடீரென வந்து என் மார்பிடையே கிழித்தது.',
        '0.22': '“மீண்டும் மீண்டும் பறந்து வந்து அது என்னைக் கடுமையாகக் கிழித்தது. அப்போது விழுந்த இரத்தத் துளிகளால் ராமன் விழித்தெழுந்தான்.',
        '0.23': '“மார்பில் காயமுற்ற என்னைக் கண்டு அந்நீண்ட கையன் நச்சுப்பாம்பு போலச் சினந்து சீறிக்கொண்டு கூறினான்:',
        '0.24': '“‘யானைத் துதிக்கை போன்ற தொடையுடையவளே, உன் மார்பிடையே காயம் செய்தது யார்? சினந்த ஐந்து தலை நாகத்துடன் விளையாடுவது யார்?’',
        '0.25': '“சுற்றிப் பார்த்த அவன், இரத்தம் தோய்ந்த கூரிய நகங்களுடன் என் எதிரே அமர்ந்திருந்த அக்காகத்தைக் கண்டான்.',
        '0.26': '“பறவைகளில் சிறந்த அக்காகம் உண்மையில் இந்திரனின் மகன்; காற்றின் வேகத்துக்கு நிகரான அது விரைவில் பூமிக்குள் சென்றது.',
        '0.27': '“அப்போது அறிவாளிகளில் சிறந்த அந்நீண்ட கையன் சினத்தால் கண்களைச் சுழற்றி அக்காகத்தின் மீது கடுமையான முடிவெடுத்தான்.',
        '0.28': '“அவன் தர்ப்பைப் பாயிலிருந்து ஒரு தர்ப்பையை எடுத்துப் பிரம்மாஸ்திரத்தால் மந்திரித்தான்; அது ஊழித்தீயைப் போல அப்பறவையின் முன் எரிந்தது.',
        '0.29': '“எரியும் அத்தர்ப்பையை அவன் காகத்தை நோக்கி எறிந்தான்; அத்தர்ப்பை வானில் காகத்தைத் துரத்திச் சென்றது.',
        '0.30': '“துரத்தப்பட்ட காகம் அப்போது பலவாறு பறந்தது; காப்பை நாடி இவ்வுலகம் முழுவதும் சுற்றித் திரிந்தது.',
        '0.31': '“தந்தையாலும் மாமுனிவர்கள் அனைவராலும் கைவிடப்பட்ட அது மூவுலகங்களையும் சுற்றி அவனிடமே அடைக்கலம் புகுந்தது.',
        '0.32': '“அடைக்கலம் தருபவனான காகுத்ஸ்தன், கொல்லத் தக்கதாயினும் தரையில் வீழ்ந்து அடைக்கலம் புகுந்த அதைக் கருணையால் காத்தான்.',
        '0.33': '“களைத்து, நிறமிழந்து, விழுந்துகொண்டிருந்த அதனிடம் அவன் கூறினான்: ‘பிரம்மாஸ்திரத்தை வீணாக்க இயலாது; என்ன செய்வது என்று சொல்.’',
        '0.34': '“அப்போது அவ்வஸ்திரம் காகத்தின் வலக்கண்ணை அழித்தது; வலக்கண்ணைக் கொடுத்து அது உயிர் பிழைத்தது.',
        '0.35': '“ராமனையும் தசரத மன்னனையும் வணங்கி, அவ்வீரனால் விடைகொடுக்கப்பட்டு அது தன் இருப்பிடத்துக்குச் சென்றது.',
        '0.36': '“என் பொருட்டு ஒரு காகத்தின் மீதும் நீ பிரம்மாஸ்திரத்தை ஏவினாய்; பூமியின் தலைவனே, உன்னிடமிருந்து என்னைக் கவர்ந்தவனை ஏன் பொறுத்துக்கொள்கிறாய்?',
        '0.37': '“மனிதச் சிறந்தோனே, பெரும் ஊக்கத்துடன் என்மேல் இரக்கம் காட்டு; நாதா, உன்னைப் போன்ற காவலன் இருந்தும் நான் துணையற்றவள் போலத் தோன்றுகிறேன்.',
        '0.38': '“இரக்கமே மேலான அறம் — இதை நான் உன்னிடமிருந்தே கேட்டேன். நீ பெரும் வீரமும் பேரூக்கமும் பெருவலிமையும் உடையவன் என்று அறிவேன்,',
        '0.39': '“கரையற்றவன், கலங்காதவன், ஆழத்தில் கடல் போன்றவன், கடலுடன் கூடிய பூமியின் தலைவன், இந்திரனுக்கு நிகரானவன்.',
        '0.40': '“இவ்வாறு அஸ்திரம் அறிந்தோரில் சிறந்தவனும், வலிமையுடையவனும், உறுதியுடையவனுமாக இருந்தும், ராகவா, அரக்கர்கள் மீது அஸ்திரத்தை ஏன் ஏவவில்லை?”',
        '0.41': '“நாகர்களோ கந்தர்வர்களோ தேவர்களோ மருத்துக் கூட்டங்களோ போரில் ராமனின் வேகத்தை எதிர்கொள்ள இயலார்.',
        '0.42': '“அவ்வீரனுக்கு என்மேல் சிறிதேனும் அக்கறை இருந்தால், கூரிய அம்புகளால் அரக்கர்களை ஏன் அழிக்கவில்லை?',
        '0.43': '“அல்லது பகைவரை வாட்டும் பெருவலிமையுடைய வீர லக்ஷ்மணன் அண்ணனின் ஆணையைப் பெற்று என்னை ஏன் காக்கவில்லை?',
        '0.44': '“வாயுவுக்கும் இந்திரனுக்கும் நிகரான ஒளியுடைய, தேவர்களாலும் வெல்ல இயலாத அம்மனிதப் புலிகள் இருவரும் என்னை ஏன் புறக்கணிக்கின்றனர்?',
        '0.45': '“ஐயமின்றி என்னால்தான் ஏதோ பெரும் தீவினை நிகழ்ந்திருக்க வேண்டும்; ஏனெனில் வல்லவர்களாயிருந்தும் அப்பகைவரை வாட்டுவோர் இருவரும் என்னைக் கவனிக்கவில்லை.”',
        '0.46': 'வைதேகி கண்ணீருடன் சொன்ன இரக்கமான சொற்களைக் கேட்டுப் பேரொளி கொண்ட வானரக் குழுத் தலைவன் ஹனுமான் கூறினான்:',
        '0.47': '“தேவி, வாய்மையின் மீது ஆணையிட்டுச் சொல்கிறேன்: உன் துயரத்தால் ராமன் எல்லாவற்றிலிருந்தும் விலகியுள்ளான்; ராமன் துயருற்றிருப்பதால் லக்ஷ்மணனும் வேதனைப்படுகிறான்.',
        '0.48': '“எப்படியோ நீ கண்டுபிடிக்கப்பட்டாய்; இது வருந்தும் நேரமல்ல. அழகியே, சிறிது நேரத்தில் உன் துயரங்களின் முடிவைக் காண்பாய்.',
        '0.49': '“உன்னைக் காணும் ஊக்கத்தால் அம்மனிதப் புலிகளான பெருவலிமையுடைய இளவரசர்கள் இருவரும் உலகங்களைச் சாம்பலாக்குவர்.',
        '0.50': '“அகன்ற கண்ணாளே, போரில் கொடியவனான ராவணனை உறவினருடன் கொன்று ராகவன் உன்னைத் தன் நகருக்கு அழைத்துச் செல்வான்.',
        '0.51': '“ராகவனிடமோ, பெருவலிமையுடைய லக்ஷ்மணனிடமோ, ஒளிமிக்க சுக்ரீவனிடமோ, கூடியுள்ள வானரர்களிடமோ என்ன சொல்ல வேண்டும் என்று சொல்.”',
        '0.52': 'அவன் இவ்வாறு கூறவே சீதை மீண்டும் சொன்னாள்: “உறுதியுள்ள கௌசல்யை எந்த உலகநாதனைப் பெற்றாளோ,',
        '0.53': '“அவனிடம் என் சார்பாக நலம் விசாரித்துத் தலைதாழ்த்தி வணங்கு. மாலைகளையும் எல்லா ரத்தினங்களையும் அன்புக்குரிய அழகிய பெண்களையும்,',
        '0.54': '“பரந்த பூமியிலும் அரிதான செல்வத்தையும் துறந்து, தந்தையையும் தாயையும் மதித்து மகிழ்வித்து,',
        '0.55': '“ராமனைப் பின்தொடர்ந்து காட்டுக்குச் சென்றவன் — யாரால் சுமித்திரை நன்மகனைப் பெற்றவளானாளோ அவ்வறவோன் — மேலான இன்பத்தைத் துறந்து மனமுவந்து',
        '0.56': '“காட்டில் அண்ணன் காகுத்ஸ்தனைக் காத்துப் பின்தொடர்கிறானோ — சிங்கம் போன்ற தோள்களும், நீண்ட கைகளும், உறுதியான மனமும், காண இனிய தோற்றமும் உடையவன்,',
        '0.57': '“ராமனிடம் தந்தையிடம் போல நடந்துகொள்பவனும் என்னைத் தாயாக நடத்தியவனுமான வீர லக்ஷ்மணன் நான் கவரப்பட்டபோது அதை அறியவில்லை.',
        '0.58': '“பெரியோருக்குப் பணிவிடை செய்பவன், சீர்மிக்கவன், திறமையுடையவன், அதிகம் பேசாதவன், இளவரசர்களில் சிறந்தவனும் அன்புக்குரியவனும், என் மாமனாரைப் போன்றவன்,',
        '0.59': '“ராமனுக்கு என்னைவிட எப்போதும் அன்புக்குரிய தம்பி லக்ஷ்மணன்; அவ்வீரன் எந்தப் பொறுப்பில் அமர்த்தப்படுகிறானோ அதைச் சுமந்து நிறைவேற்றுகிறான்.',
        '0.60': '“எவனைக் கண்டு ராகவன் மறைந்த தன் உத்தமத் தந்தையையும் நினைப்பதில்லையோ, அவனிடம் என் பொருட்டு என் சொல்லாக நலம் விசாரி.',
        '0.61': '“லக்ஷ்மணன் எப்போதும் மென்மையானவன், தூயவன், திறமையானவன், ராமனுக்கு அன்புக்குரியவன்; வானரச் சிறந்தோனே, அவன் என் துயரத்தை முடிக்கும்படி செய்.',
        '0.62': '“வானரக் குழுத் தலைவனே, இக்காரியத்தை நிறைவேற்றுவதில் நீயே பொறுப்பு; உன் முயற்சியால் ராகவன் என் பொருட்டு முனைந்து செயல்படட்டும்.',
        '0.63': '“என் நாதனான வீர ராமனிடம் இதை மீண்டும் மீண்டும் சொல்: ‘தசரதன் மைந்தனே, நான் ஒரு மாதம் உயிரைத் தாங்கியிருப்பேன்.',
        '0.64': '“‘மாதத்துக்குப் பின் நான் உயிர்வாழ மாட்டேன்; இதை உண்மையாகச் சொல்கிறேன். வீரனே, தீவினையாளன் ராவணனால் வஞ்சகமாகச் சிறைப்படுத்தப்பட்ட என்னை, பாதாளத்திலிருந்து கௌசிகி மீட்கப்பட்டது போல நீ மீட்க வேண்டும்.’”',
        '0.65': 'பின்பு ஆடையில் முடிந்து வைத்திருந்த அழகிய தெய்வீகச் சூடாமணியை அவிழ்த்து, “இதை ராகவனிடம் கொடு” என்று சீதை ஹனுமானிடம் கொடுத்தாள்.',
        '0.66': 'ஒப்பற்ற அம்மணியைப் பெற்ற அவ்வீரன் அதைத் தன் விரலில் அணிந்தான்; ஏனெனில் அது அவனது கையில் நுழையவில்லை.',
        '0.67': 'மணியைப் பெற்று வணங்கி, அவ்வானரச் சிறந்தோன் சீதையை வலம் வந்து தலைதாழ்த்திப் பக்கத்தில் நின்றான்.',
        '0.68': 'சீதையைக் கண்டதால் உண்டான பெருமகிழ்ச்சியால் நிறைந்த அவன் மனதால் ராமனிடமும் நல்லிலக்கணமுடைய லக்ஷ்மணனிடமும் சென்றான்.',
        '0.69': 'ஜனக மன்னனின் மகள் தன் மாட்சியால் அணிந்திருந்த விலையுயர்ந்த அம்மணியைப் பெற்று, புயலின் தாக்குதலிலிருந்து விடுபட்ட சிறந்த மலை போல, மகிழ்ந்த மனதுடன் அவன் திரும்பிச் செல்ல ஆயத்தமானான்.',
        '0.70': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் முப்பத்தெட்டாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-39': {
      verses: {
        '0.0': 'மணியைக் கொடுத்த பின் சீதை ஹனுமானிடம் கூறினாள்: “இந்த அடையாளம் ராமனுக்கு உண்மையில் நன்கு தெரிந்ததே.',
        '0.1': '“மணியைக் கண்டதும் வீர ராமன் மூவரை நினைவுகூர்வான்: என் தாயை, என்னை, தசரத மன்னனை.',
        '0.2': '“வானரச் சிறந்தோனே, இக்காரியத்தின் ஊக்கத்தால் மீண்டும் தூண்டப்பட்டு, அடுத்து என்ன செய்ய வேண்டும் என்று சிந்தி.',
        '0.3': '“வானரச் சிறந்தோனே, இக்காரியத்தை நிறைவேற்றுவதில் நீயே பொறுப்பு; என் துயரத்தை முடிக்கும் முயற்சி எது என்று சிந்தி.',
        '0.4': '“ஹனுமானே, முயன்று என் துயரத்தை முடிவுக்குக் கொண்டு வா.” “அப்படியே ஆகட்டும்” என்று உறுதியளித்து அச்சந்தரும் வீரமுடைய மாருதி,',
        '0.5': 'வைதேகியைத் தலைதாழ்த்தி வணங்கிப் புறப்பட ஆயத்தமானான். வாயுமைந்தனான வானரன் புறப்படுவதை அறிந்து தேவி,',
        '0.6': 'மைதிலி கண்ணீரால் தழுதழுத்த குரலில் கூறினாள்: “ஹனுமானே, ராம லக்ஷ்மணர் இருவருக்கும் என் நலத்தைச் சொல்,',
        '0.7': '“வானரச் சிறந்தோனே, அமைச்சர்களுடன் சுக்ரீவனுக்கும் முதிய வானரர் அனைவருக்கும் அறமுறைப்படி என் நலத்தைச் சொல்.',
        '0.8': '“என்னைச் சூழ்ந்துள்ள இத்துயர வெள்ளத்திலிருந்து நீண்ட கையனான ராகவன் என்னைக் கரையேற்றும்படி நீ ஏற்பாடு செய்ய வேண்டும்.',
        '0.9': '“புகழுடைய ராமன் என்னை உயிருடன் இருக்கும்போதே காணும்படி, ஹனுமானே, நீ சொல்; உன் சொல்லால் அறப்பயனைப் பெறு.',
        '0.10': '“நான் சொன்ன சொற்களைக் கேட்டு, எப்போதும் ஊக்கமுடைய தசரதன் மைந்தனின் ஆண்மை என்னை அடைவதற்காகப் பெருகும்.',
        '0.11': '“என் செய்தி அடங்கிய சொற்களை உன்னிடமிருந்து கேட்டதுமே வீர ராகவன் முறைப்படி வீரச்செயலில் மனம் செலுத்துவான்.”',
        '0.12': 'சீதையின் அச்சொற்களைக் கேட்டு வாயுமைந்தன் ஹனுமான் தலைமேல் கைகூப்பி இவ்வாறு பதில் கூறினான்:',
        '0.13': '“சிறந்த வானரர்களாலும் கரடிகளாலும் சூழப்பட்டு காகுத்ஸ்தன் விரைவில் வருவான்; போரில் பகைவரை வென்று உன் துயரை நீக்குவான்.',
        '0.14': '“அவன் அம்புகளைப் பொழியும்போது அவன் முன் நிற்கத் துணிபவனை மனிதர்களிலோ அசுரர்களிலோ தேவர்களிலோ நான் காணவில்லை.',
        '0.15': '“அவன் போரில் கதிரவனையும் மழைத்தேவன் பர்ஜன்யனையும் விவஸ்வானின் மகன் யமனையும் தாங்கக்கூடியவன் — அதிலும் குறிப்பாக உனக்காக.',
        '0.16': '“கடல் வரை பரந்த பூமியை வெல்ல அவன் வல்லவன்; ஜனகன் மகளே, ராமனின் வெற்றி உன் பொருட்டே நிகழும்.”',
        '0.17': 'நன்கு சொல்லப்பட்ட, முற்றிலும் உண்மையான அவனது சொற்களைக் கேட்டு ஜானகி அவனைப் பெரிதும் மதித்து இவ்வாறு கூறினாள்:',
        '0.18': 'பின்பு புறப்படும் அவனை மீண்டும் மீண்டும் நோக்கிச் சீதை, நட்புணர்வால் கணவன் மீதான அன்பு நிறைந்த சொற்களை மதிப்புடன் கூறினாள்:',
        '0.19': '“வீரனே, பகைவரை அடக்குபவனே, உனக்குச் சரியெனப்பட்டால் ஏதேனும் மறைவான இடத்தில் ஒரு நாள் தங்கி, ஓய்வெடுத்து நாளை செல்.',
        '0.20': '“வானரனே, உன் அண்மையால் அதிருஷ்டமற்ற எனக்கு இப்பெருந்துயரிலிருந்து சிறிது நேரமாவது விடுதலை கிடைக்கும்.',
        '0.21': '“வானரப் புலியே, நீ சென்ற பின் மீண்டும் வரும் வரை என் உயிரைப் பற்றியும் ஐயமே; இதில் சந்தேகமில்லை.',
        '0.22': '“வானரனே, துயர் மேல் துயரால் வாடும் என்னை உன்னைக் காணாத துயரம் எரிப்பது போல மீண்டும் வாட்டும்.',
        '0.23': '“வீரனே, வானரத் தலைவனே, உன் துணைவர்களான வானரர், கரடிகள் பற்றி இப்பெரும் ஐயம் என் முன் நிற்பது போலுள்ளது:',
        '0.24': '“அவ்வானர, கரடிப் படைகளோ, மனிதர்களில் சிறந்தவனின் அவ்விரு மைந்தர்களோ கடக்க இயலாத அப்பெருங்கடலை எப்படிக் கடப்பர்?',
        '0.25': '“இங்கே கடலைத் தாண்டும் வல்லமை மூவருக்கே உண்டு: விநதையின் மகன் கருடனுக்கு, உனக்கு, அல்லது வாயுவுக்கு.',
        '0.26': '“ஆகவே வீரனே, இவ்வாறு கடினமான இக்காரியத்தில் நீ என்ன தீர்வு காண்கிறாய்? செயலறிந்தோரில் நீயே சிறந்தவன்.',
        '0.27': '“பகை வீரர்களைக் கொல்பவனே, இக்காரியத்தை நிறைவேற்ற நீ ஒருவனே போதும் என்பது உண்மைதான்; அதன் பலன் உனக்குப் புகழைத் தரும்.',
        '0.28': '“ஆனால் அவன் முழுப் படையுடன் போரில் ராவணனை வென்று, வெற்றியாளனாய் என்னைத் தன் நகருக்கு அழைத்துச் சென்றால் அதுவே அவனுக்குத் தகும்.',
        '0.29': '“பகைப்படையை நசுக்கும் காகுத்ஸ்தன் இலங்கையைத் தன் படைகளால் நிரப்பி என்னை அழைத்துச் சென்றால், அது அவனுக்குத் தகும்.',
        '0.30': '“ஆகவே போர்வீரனான அம்மகாத்மாவின் வீரத்துக்கு ஏற்ற வகையில் நிகழும்படி நீ ஏற்பாடு செய்.”',
        '0.31': 'பொருள் நிறைந்த, பணிவான, காரணங்கள் கொண்ட அச்சொற்களைக் கேட்டு ஹனுமான் இறுதிப் பதிலைக் கூறினான்:',
        '0.32': '“தேவி, வானர, கரடிப் படைகளின் தலைவனும் தாவுவோரில் சிறந்தவனும் வாய்மையுடையவனுமான சுக்ரீவன் உன் காரியத்துக்காக உறுதியான முடிவு எடுத்துள்ளான்.',
        '0.33': '“வைதேகி, கோடிக்கணக்கான ஆயிரம் வானரர்கள் சூழ, அரக்கர்களை அழிக்கும் அவன் விரைவில் வருவான்.',
        '0.34': '“அவன் ஆணையின் கீழ் வீரமுடைய, உறுதியுள்ள, பெருவலிமையுடைய, மனவேகத்தில் செல்லும் வானரர்கள் உள்ளனர்.',
        '0.35': '“அவர்களின் இயக்கம் மேலேயோ கீழேயோ பக்கவாட்டிலோ தடைபடாது; அளவற்ற ஒளியுடைய அவர்கள் பெருஞ்செயல்களில் ஒருபோதும் சோர்வதில்லை.',
        '0.36': '“பேரூக்கமுடைய, காற்றின் வழியே செல்லும் அவர்கள் கடல்களும் மலைகளும் கொண்ட பூமியைப் பலமுறை வலம் வந்துள்ளனர்.',
        '0.37': '“அங்கே என்னைவிடச் சிறந்த, எனக்கு நிகரான வனவாசிகள் உள்ளனர்; சுக்ரீவனின் அருகில் என்னைவிடத் தாழ்ந்தவர் எவருமில்லை.',
        '0.38': '“நானே இங்கு வந்துவிட்டபோது அப்பெருவலியோரைப் பற்றிச் சொல்வதென்ன! சிறந்தோர் தூதர்களாக அனுப்பப்படுவதில்லை; மற்றவர்களே அனுப்பப்படுவர்.',
        '0.39': '“ஆகவே தேவி, வேதனை போதும்; உன் துயர் நீங்கட்டும். வானரக் குழுத் தலைவர்கள் ஒரே தாவலில் இலங்கையை அடைவர்.',
        '0.40': '“உதித்த சந்திர சூரியர் போல என் முதுகில் அமர்ந்த அம்மனிதச் சிங்கங்கள் இருவரும் பெரும் படைகளுடன் உன்னிடம் வருவர்.',
        '0.41': '“அவ்விரு வீரர்களான மனிதச் சிறந்தோர், ராம லக்ஷ்மணர் சேர்ந்து இலங்கை நகருக்கு வந்து அம்புகளால் அதை அழிப்பர்.',
        '0.42': '“பரிவாரத்துடன் ராவணனைக் கொன்று ரகுநந்தனனான ராகவன், அழகியே, உன்னை அழைத்துக்கொண்டு தன் நகருக்குத் திரும்புவான்.',
        '0.43': '“ஆகவே ஆறுதல் கொள், உனக்கு நலம் உண்டாகட்டும்; தக்க காலத்தை எதிர்நோக்கு. விரைவில் எரியும் நெருப்புப் போன்ற ராமனைக் காண்பாய்.',
        '0.44': '“மைந்தர், அமைச்சர், உறவினருடன் அரக்கர் வேந்தன் கொல்லப்பட்டதும், சந்திரனுடன் ரோகிணி போல நீ ராமனுடன் சேர்வாய்.',
        '0.45': '“தேவி மைதிலி, விரைவில் உன் துயரத்தின் மறுகரையைக் காண்பாய்; ராமனின் வலிமையால் கொல்லப்பட்ட ராவணனையும் காண்பாய்.”',
        '0.46': 'இவ்வாறு வைதேகியைத் தேற்றி, புறப்பட முடிவெடுத்த வாயுமைந்தன் ஹனுமான் வைதேகியிடம் மீண்டும் கூறினான்:',
        '0.47': '“பகைவரைக் கொல்பவனும் தன்னை வென்றவனுமான ராகவனையும் கையில் வில்லேந்திய லக்ஷ்மணனையும் இலங்கை வாயிலுக்கு வந்திருப்பதை விரைவில் காண்பாய்.',
        '0.48': '“நகங்களையும் பற்களையும் ஆயுதமாகக் கொண்ட, சிங்கம் புலி போன்ற வீரமுடைய, யானையரசர்கள் போன்ற வீர வானரர்கள் கூடியிருப்பதை விரைவில் காண்பாய்.',
        '0.49': '“உத்தமியே, இலங்கையின் மலய மலைச் சரிவுகளில் மலைகளையும் மேகங்களையும் போன்ற, முழங்கும் வானரத் தலைவர்களின் பல கூட்டங்களைக் காண்பாய்.',
        '0.50': '“மன்மதனின் கொடிய அம்பால் உயிர்நிலையில் தாக்கப்பட்ட ராமன், சிங்கத்தால் தாக்கப்பட்ட யானை போல அமைதி பெறவில்லை.',
        '0.51': '“தேவி, துயரால் அழாதே; உன் மனதில் அச்சம் வேண்டாம். அழகியே, கணவன் இந்திரனுடன் சசி போல நீயும் உன் கணவனுடன் சேர்வாய்.',
        '0.52': '“ராமனைவிடச் சிறந்தவன் வேறு யார்? சௌமித்ரிக்கு நிகரானவன் யார்? நெருப்பையும் காற்றையும் போன்ற அவ்விரு உடன்பிறந்தோரே உனக்கு அடைக்கலம்.',
        '0.53': '“தேவி, அரக்கர் கூட்டங்கள் வாழும் மிகக் கொடிய இவ்விடத்தில் நீ நெடுங்காலம் இருக்க மாட்டாய். உன் அன்பனின் வருகை தாமதமாகாது; நான் அவனைச் சந்திக்கும் வரை மட்டும் பொறுத்துக்கொள்.”',
        '0.54': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் முப்பத்தொன்பதாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
  },
};
